\label{Intro:Structure}
Let $A$ be a simple separable  nuclear non-elementary $C^*$-algebra. Then the following are equivalent:
\begin{enumerate}
\item\label{tw1} $A$ has finite nuclear dimension;
\item[\namedlabel{tw1prime}{(i')}] $A$ has nuclear dimension at most one;
\item\label{tw2} $A$ is $\mathcal Z$-stable;
\item\label{tw3} $A$ has almost unperforated Cuntz 
semigroup;
\item[\namedlabel{tw3prime}{(iii')}] $A$ is pure.
\end{enumerate}

Let $A$ be a simple separable unital  nuclear $C^*$-algebra. Suppose that either
\begin{enumerate}
    \item\label{it:winter1}  $A$ is non-elementary and of finite nuclear dimension, or
    \item\label{it:winter2} $A$ is pure and of locally finite nuclear dimension.
\end{enumerate}
Then $A$ is $\mathcal Z$-stable.

\label{def:traciallyPure}
    Let $(\mathcal{M},X)$ be a tracially complete $C^*$-algebra. 
    \begin{enumerate}
        \item \label{tt:traciallypure-1} Let $a,b\in \mathcal{M}_+$. Say that $a$ is \emph{$(2,X)$-Cuntz subequivalent to $b$}, written $a\precsim_X b$, if there exists a sequence $(v_m)\in\mathcal{M}$ with $\|v_m^*bv_m-a\|_{2,X}\to 0$.  
        \item \label{tt:traciallypure-2} Say that $(\mathcal{M},X)$ has \emph{strict $(2,X)$-comparison} if for all $n\in\mathbb N$ and $a,b\in M_n(\mathcal{M})_+$ with $d_\tau(a)<d_\tau(b)$ for all $\tau\in X$,\footnote{Each $\tau \in X$ is viewed as a trace on $M_n(\mathcal{M})$ with trace $n$.} we have $a\precsim_{X}b$ in $M_n(\mathcal{M})$.
        \item \label{tt:traciallypure-3}Say that $(\mathcal{M},X)$ has \emph{approximately constant rank functions} if for each $\lambda>0$ and $\epsilon>0$ there exists $n\in\mathbb N$ and a positive element $a\in M_n(\mathcal{M})_+$ such that $\sup_{\tau\in X}|d_\tau(a)-\lambda|<\epsilon$.
    \end{enumerate}

\label{PurenessThm} Let $(\mathcal{M},X)$ be a II$_1$ factorial tracially complete $C^*$-algebra.  Then the following are equivalent:
\begin{enumerate}
    \item \label{it:Pureness.1} $(\mathcal{M},X)$ has strict $(2, X)$-comparison and has approximately constant rank functions.
    \item \label{it:Pureness.3}  $\mathcal M$ has strict comparison with respect to $X$ and $\mathcal M$ has divisible unit;
    \item \label{it:Pureness.4}  $(\mathcal{M},X)$ has classification of projections and $\mathcal M$ has real rank zero.
\end{enumerate}
In this case, $T(\mathcal M) = X$ and $\mathcal M$ is pure and has stable rank one.

\label{TC:Structure}
    Let $(\mathcal M,X)$ be type II$_1$ factorial amenable tracially complete $C^*$-algebra. The following are equivalent:
    \begin{enumerate}
        \item $(\mathcal M,X)$ is hyperfinite;
        \item $(\mathcal M,X)$ is McDuff;
        \item[(ii$'$)] $(\mathcal M,X)$ has property $\Gamma$;
        \item $(\mathcal M,X)$ is regular.
    \end{enumerate}

\label{RobotLemma}
    Let $\mathcal{M}$ be a $\|\cdot\|_{2,u}$-separable $W^*$-bundle over $K$ whose fibres are all isomorphic to copies of the  hyperfinite II$_1$ factor. Suppose $\mathcal{M}$ has classification of projections and real rank zero. Then $\mathcal{M}$ has the property that for all finite subsets $\mathcal F\subset\mathcal M$ and $\epsilon>0$, and $0<\gamma_0$, there exists a projection $p\in\mathcal{M}$ with constant trace $\gamma_p$ for some $0<\gamma_p<\gamma_0$ such that
 \begin{equation}\label{2.2:E1}
     \sup_{\tau\in K}\|[x,p]\|_{2,\tau}^2\leq \epsilon^2\gamma_p,\quad x\in\mathcal F. 
 \end{equation}

Fix a finite set $\mathcal F \subseteq \mathcal M$ consisting of positive contractions and $\delta > 0$.  For each $\tau \in K$, $\pi_\tau(\mathcal M) \cong \mathcal R$, so classification of projections in $\mathcal M$ allows us to find a finite-dimensional matrix algebra $F \subseteq \mathcal M$ which $(2,\tau)$-approximately contains $\mathcal F$ in the sense that for all $x \in \mathcal F$, there is $y \in F$ such that $\|x - y\|_{2, \tau} < \epsilon$.
A standard compactness argument provides a finite open cover $K = \bigcup_{i=1}^n U_i$ and finite-dimensional matrix algebras $F_1, \ldots, F_n \subseteq \mathcal M$ such that for each $i = 1, \ldots, n$ and $\tau \in U_i$, $\mathcal F$ is $\|\cdot\|_{2,\tau}$-approximately contained in $F_i$.  Fix a partition of unity $f_1, \ldots, f_n \in C(K)_+$ subordinate to $(U_i)_{i=1}^n$, i.e. $\sum_{i=1}^n f_i = 1$ and $\mathrm{supp}(f_i) \subseteq U_i$.  

The goal is to produce a small constant $\gamma>0$ and mutually orthogonal projections $p_1, \ldots, p_n \in \mathcal M$ such that $p_i$ commutes with $F_i$ and $\tau(p_i) = \gamma f_i(\tau)$ for all $\tau \in K$.  Once this has been done, $p \coloneqq \sum_{i=1}^n p_i \in \mathcal M$ is a projection with $\tau(p) = \gamma$ for all $\tau \in K$.  Further, since $p_i$ commutes with $F_i$ and $\mathcal F$ is $(2, \tau)$-approximately contained in $F_i$ whenever $\tau(p_i) = \gamma f_i(\tau) \neq 0$, one expects $p$ to approximately commute with $\mathcal F$.  A computation shows that if $x \in \mathcal F$ and $y_i \in F_i$ for $i = 1, \ldots, n$, then
\begin{equation}
    \|[x, p]\|_{2, \tau}^2 = \sum_{i=1}^n \big( \|(x - y_i) p_i\|_{2, \tau}^2 + \|p_i (x - y_i)\|_{2, \tau}^2 \big), \quad \tau \in K. 
\end{equation}
\emph{If} for each $i=1,\dots,n$, we could obtain the bound 
\begin{equation}\label{E1.5}
    \|(x - y_i)p_i\|_{2, \tau}^2 \leq \|x - y_i\|_{2, \tau}^2 \tau(p_i) = \gamma f_i(\tau) \|(x - y_i)\|_{2, \tau}^2,\quad \tau\in K 
\end{equation}
then it would follow that $p$ is approximately central.

The crucial ingredient is choosing $p_i$ (and the $y_i$) so that $x_i - y_i$ has small operator norm on the corner under $p_i$ allowing us to achieve an estimate of the form \eqref{E1.5}.  To do this, we refine the approach above slightly.  For each $x \in \mathcal F$, let $y_{x, i} \in \mathcal F_i$ be positive contractions chosen to be $(2, \tau)$-close to $x$ whenever $\tau \in U_i$ and set
\begin{equation}
    a_i = \sum_{x \in \mathcal F} (x - y_{x, i})^2,
\end{equation}
so that $\tau(a_i)$ is small if and only if $\mathcal F$ is $(2, \tau)$-approximately contained in $F_i$. Adjusting the initial estimates as necessary, we can arrange
\begin{equation}
    \sup_{\tau \in X} \min_{1 \leq i \leq n} \tau(a_i) < \delta/32.
\end{equation}

For a sufficiently small $\gamma > 0$, the projections $p_1, \ldots, p_n$ are constructed inductively as follows.  Let $E_1 \colon \mathcal M \rightarrow \mathcal M \cap F_1'$ denote the canonical conditional expectation.  Since $\mathcal M \cap F_1'$ is isomorphic to a corner of $\mathcal M$, our generous assumption allows us to take the spectral projection $q_1 \in \mathcal M \cap F_1'$ of $E_1(a_1)$ on the interval $[0, \delta/2]$.  Then one computes $\tau(q_1) \geq 1/4$ for all $\tau \in U_i$, so the classification of projections in $\mathcal M \cap F_1'$ allows one to construct a projection $p_1 \in \mathcal M \cap F_1'$ such that $\tau(p_1) = \gamma f_1(\tau)$ for all $\tau \in K$ (assuming $\gamma < 1/4)$.  The key estimate that will allow us to show $p_1$ (and eventually $p$) is approximately central is $p_1 a_1 p_1 \leq \delta p_1$.

Assuming $p_1, \ldots, p_{i-1}$ have been constructed, one repeats the construction above replacing $E_1(a_1)$ with 
\begin{equation}
    E_i(a_i) + \dim(F_i) E_i(p_1 + \ldots p_{i -1}).
\end{equation}
So long as $\gamma$ is sufficiently small, the resulting projection $\tilde p_i\in\mathcal M\cap F_i$ will be (operator norm) approximately orthogonal to $p_1, \ldots, p_{i-1}$, and a standard polar decomposition argument produces a partial isometry $v_i$ with $v_i^*v_i=\tilde{p}_i$ and $v_i\approx \tilde{p_i}$ and a projection $p_i\coloneqq v_iv_i^* \in \mathcal M$ close to $\tilde p_i$ and approximately orthogonal to $p$.  Note that $\gamma$ depends on the integer $n \in \mathbb N$ coming from the compactness argument and the dimension of the approximately finite-dimensional subalgebras $F_i$.

\label{def:cuntz-omnibus} 
Let $A$ be a $C^*$-algebra.
\begin{enumerate}
    \item An element $x \in \operatorname{{Cu}}(A)$ is said to be \emph{almost divisible} if for any $x' \in \operatorname{{Cu}}(A)$ such that $x' \ll x$ and any integer $k \geq 1$ there exists $y \in \operatorname{{Cu}}(A)$ with $ky \leq x$ and $x' \leq (k+1)y$.\footnote{Note that in some references the ``cutdown'' from $x$ to $x'$ in the definition of almost divisibility is omitted, leading to the formally stronger requirement on $y$ that $ky \leq x \leq (k+1)y$; see \cite[Remark 7.3.5]{APT:MAMS} for a discussion of the reasons behind this.}
    \item If all $x \in \operatorname{{Cu}}(A)$ are almost divisible, then $\operatorname{{Cu}}(A)$ is said to be \emph{almost divisible}.
    \item The Cuntz semigroup $\operatorname{{Cu}}(A)$ is said to be \emph{almost unperforated} if for all $x,y \in \operatorname{{Cu}}(A)$, the implication
    \begin{equation}
        (k+1)x \leq ky\text{ for some }k\in\mathbb N\Longrightarrow x\leq y
    \end{equation}holds.  
    \item The $C^*$-algebra $A$ is said to be \emph{pure} if $\operatorname{{Cu}}(A)$ is both almost unperforated and almost divisible.
\end{enumerate}

\label{sc_bdd_trace_W}   
Let $A$ be a $C^*$-algebra and $X$ be a compact subset of $T(A)$. Then we say $A$ has \emph{strict comparison with respect to $X$} if 
\begin{equation}
\bigl(\forall \tau \in X,\ d_\tau(a) < d_\tau(b)\bigr)
\implies a \precsim b  
\end{equation}
for all $n \in \mathbb{N}$ and non-zero $a,b \in M_n(A)_+$.

Let $W(A)$ denote the uncompleted Cuntz semigroup on $A$, let $G(A)$ denote its Grothendieck group, and let $g \colon W(A) \rightarrow G(A)$ denote the canonical map.  Define
    \begin{equation}
        G(A)_+ = \{g(y) - g(x) : x, y \in W(A),\ x \leq y \} \subseteq G(A)
    \end{equation}
    and $1_{G(A)} = g([1_A])$.  With this structure, $G(A)$ is an ordered abelian group with order unit.

    Note that every $\tau \in T(A)$ induces a state $d_\tau \colon W(A) \rightarrow [0,\infty)$, which in turn induces a state $\bar d_\tau \colon G(A) \rightarrow \mathbb R$.  Suppose $h, k \in G(A)$ are such that $\bar d_\tau(h) < \bar d_\tau(k)$ for all $\tau \in X$.  Let $x, y, x', y' \in W(A)$ be such that $h = x - x'$ and $k = y - y'$.  
    Then $d_\tau(x + y') < d_\tau(x' + y)$ for all $\tau \in X$.  Since $A$ has strict comparison with respect to $X$, we have $x + y' \leq x' +y$, so $h \leq k$.

    By \cite[Corollary~7.11]{Goodearl:Book}, every state on $G(A)$ has the form $\bar d_\tau$ for some $\tau \in X$.  Now fix $\sigma \in T(A)$.  Then there is $\tau \in X$ such that $\bar d_\sigma = \bar d_\tau$.  Then $d_\sigma = d_\tau$ as states on $W(A)$.  Now, for all $a \in A_+$,
    \begin{equation}
        \sigma(a) = \int_0^\infty d_\sigma((a - t)_+) \, dt = \int_0^\infty d_\tau((a-t)_+) \, dt = \tau(a),
    \end{equation}
    so $\sigma = \tau \in X$.

\label{prop:rr0-comparison}
	Let $A$ is a $C^*$-algebra real rank zero and let $X \subseteq T(A)$ be a compact non-empty set of traces.  The following are equivalent:
	\begin{enumerate}
		\item\label{it:rr0-comp-pos} $A$ has strict comparison with respect to $X$;
		\item\label{it:rr0-comp-proj} For all $n \in \mathbb N$ and projections $p, q \in M_n(A)$, if $\tau(p) < \tau(q)$ for all $\tau \in X$, then $p \precsim q$.
	\end{enumerate}

\label{thm:sr1facts}
    Let $A$ be a unital $C^*$-algebra with stable rank one. Then
    \begin{enumerate}
        \item (Rieffel, \cite[Theorem 2.10]{rieffel87}) \label{it:sr1Rieffel} $A$ is $K_1$-bijective, i.e.\ the canonical mapping $U(A)/U_0(A) \to K_1(A)$ is bijective.
        \item (Brown, \cite[Theorem~1]{Brown95}) \label{it:BrownTrick} If $p,q\in A$ are projections that are Murray--von Neumann equivalent, then they are homotopic and therefore unitarily equivalent via a unitary in the path component of the identity.
    \end{enumerate}

Define $F,G:X \rightarrow \mathbb{R}$ by
    \begin{equation}
        F(x) \coloneqq \begin{cases}
            f(x), & x \in Y, \\
            0,   & x \not\in Y,
        \end{cases}
        \quad \text{and} \quad
        G(x) \coloneqq \begin{cases}
            f(x), & x \in Y, \\
            g(x), & x \not\in Y.
        \end{cases}       
    \end{equation}
    Then $F$ is upper-semicontinuous and convex, $G$ is lower-semicontinuous and concave, and $0 \leq F \leq G$. 
    \footnote{Proof that $G$ is concave and lower-semicontinuous (similar proofs work for $F$): Let $x_1,x_2 \in X$ and $\lambda \in (0,1)$. Set $x_3 = \lambda x_1+(1-\lambda)x_2$. We claim that $G(x_3) \geq \lambda G(x_1)+ (1-\lambda)G(x_2)$. This is clear if $x_3 \not\in Y$ as then $G(x_3) \geq G(x_1), G(x_2)$. If $x_3 \in Y$, then $x_1,x_2 \in Y$ as $Y$ is a face, so we have $G(x_3) = \lambda G(x_1)+ (1-\lambda)G(x_2)$ as $G|_Y = f$ and $f$ is affine.  Clearly $G$ is continuous on $X \setminus Y$. Let $x_0 \in Y$ and suppose $G(x_0) > c$. Then $g(x_0) \geq f(x_0) > c$. By continuity of $g$ and $f$, there is $U$ open in $Y$ such that $f(x) > c$ for $x \in U$ and also $V$ open in $X$ such that $g(x) > c$ for $x \in V$. Choose an open neighbourhood $W$ of $x_0$ in $X$ such that $W \subseteq V$ and $W \cap Y \subseteq U$. Then $G(x) > c$ for $ x \in W$.  
    } 
    By Theorem~\ref{thm:edwards}, there exists $h \in \operatorname{Aff}(X)$ such that $F(x) \leq h(x) \leq G(x)$ for all $x \in X$.
    As $f\leq g|_Y$, we have $G \leq g$, and so $h \leq g$. As $F \geq 0$, we have $h \geq 0$. Since $F(y) = G(y) = f(y)$ for all $y \in Y$, it follows that $h|_Y = f$.

\label{cor:riesz-properties}
    Let $X$ be a compact convex set. Then the following are equivalent.
    \begin{enumerate}
        \item $X$ is a Choquet simplex;
        \item Given $a_1,a_2,b_1,b_2 \in \operatorname{{Aff}}(X)$ with $a_i \leq b_i$ for $i \in \{1,2\}$. There exists $h \in \operatorname{{Aff}}(X)$ such that $a_i \leq h \leq b_i$ for for $i \in \{1,2\}$ (Riesz interpolation).
        \item Given $a, b_1,b_2 \in \operatorname{{Aff}}(X)$ with $0 \leq a \leq b_1 + b_2$. There exist $a_1, a_2 \in \operatorname{{Aff}}(X)$ such that $a = a_1 + a_2$ and $0 \leq a_i \leq b_i$ for $i \in \{1,2\}$ (Riesz decomposition).
    \end{enumerate}

\label{Rem:MoreRieszDecomp}
    Note that from the Riesz decomposition property, if $X$ is a Choquet simplex and $a_1,\dots,a_n,b_1,\dots,b_m\in\operatorname{{Aff}}(X)_+$ satisfy $\sum_{i=1}^na_i\leq\sum_{j=1}^mb_j$, then there exist $a_{i,j}\in \operatorname{{Aff}} (X)_+$ for $i=1,\dots,n$ and $j=1,\dots,m$ such that 
    \begin{equation} a_i=\sum_{j=1}^ma_{i,j} \text{ for all }i\text{ and } \sum_{i=1}^na_{i,j}\leq b_j \text{ for all }j. \end{equation}
    See the proof of \cite[Proposition 2.2]{Goodearl:Book}, for a similar argument.

\label{def:TC}
	A \emph{tracially complete $C^*$-algebra} is a pair $(\mathcal{M},X)$ where $\mathcal{M}$ is a unital $C^*$-algebra and $X \subseteq T(\mathcal{M})$ is a non-empty compact convex set such that
	\begin{enumerate}
		\item the uniform 2-seminorm $\|\cdot\|_{2,X}$ is a norm on $\mathcal{M}$, 
		\item the $\|\cdot\|$-closed unit ball of $\mathcal{M}$ is $\|\cdot\|_{2,X}$-complete,
	\end{enumerate}
    where $\|\cdot\|_{2,X}:\mathcal{M} \rightarrow [0,\infty)$ is given by $\|a\|_{2,X} \coloneqq \sup_{\tau \in X} \tau(a^*a)^{1/2}$ for $a \in \mathcal{M}$.

\label{strict_compa_A_ultrap} 
    Let $A$ be a $C^*$-algebra with $T(A)$ non-empty and compact. Suppose $A$ has strict comparison with respect to $T(A)$. 
    Then $A^\omega$ has strict comparison with respect to $\overline{T_\omega(A)}$, and $T(A^\omega)=\overline{T_\omega(A)}$.  In particular if $(\mathcal{M},X)$ is a factorial II$_1$ tracially complete $C^*$-algebra and $\mathcal{M}$ has strict comparison with respect to $X$, then $\mathcal{M}^\omega$ has strict comparison with respect to $X^\omega$.

\label{lem:EpsTest}
	Let $(\Omega_n)_{n=1}^\infty$ be a sequence of non-empty sets, and for $k,n\in\mathbb N$, let $h^{(k)}_n\colon \Omega_n\rightarrow [0,\infty]$ be a function.  Define functions $h_\omega^{(k)}\colon \prod_{n=1}^\infty \Omega_n \to [0,\infty]$ by
	\begin{equation}
		\label{eq:EpsTest1}
		h_\omega^{(k)}(x_1,x_2,\dots) \coloneqq \lim_{n\to\omega} h^{(k)}_n(x_n). 
	\end{equation}
	If for every $\epsilon>0$ and $k_0\in\mathbb N$, there exists $x\in \prod_{n=1}^\infty \Omega_n$ such that $h^{(k)}(x)<\epsilon$ for all $k\in\{1,\dots,k_0\}$, then there exists $y\in \prod_{n=1}^\infty \Omega_n$ such that $h^{(k)}(y)=0$ for all $k\in\mathbb N$.

\label{lem:trace-trick}
    Let $A$ be a $C^*$-algebra, $X$ be a non-empty compact subset of $T(A)$, and $X^\omega$ be the weak$^*$ closure of the limit traces coming from $X$.
    Let $(a_n)_{n=1}^\infty \in \ell^\infty(A)$. Then 
    \begin{equation}
        \lim_{n \to \omega} \sup_{\tau \in X} |\tau(a_n)| = \sup_{\tau_\omega \in X^\omega} |\tau_{\omega}((a_n)_{n=1}^\infty)|. 
    \end{equation}
    Moreover, $\lim_{n \to \omega} \|a_n\|_{2,X} = \|(a_n)_{n=1}^\infty\|_{2,X^\omega}$.

\label{prop:CP}
	Let $A$ be a unital $C^*$-algebra and let $f\colon T(A) \to \mathbb R$ be a continuous affine function.
	Then for any $\epsilon>0$, there is a self-adjoint element $a \in A$ such that
	\begin{equation} \label{eqn:CP}
        \|a\| \leq \|f\|_\infty + \epsilon \quad \text{and} \quad \tau(a) = f(\tau), \quad \tau \in T(A).
    \end{equation}
	If $f$ is strictly positive, i.e.\ $f(\tau) > 0$ for all $\tau \in T(A)$, then we may assume $a \geq 0$.

\label{prop:CP-ultrapowers}
    Let $(\mathcal{M},X)$ be a factorial tracially complete $C^*$-algebra and let $f\in \operatorname{{Aff}}(T(\mathcal{M}^\omega))$. Then there exists self-adjoint element $a \in \mathcal{M}^\omega$ such that 
    \begin{equation} \label{eqn:CP-ultrapowers}
       \|a\| \leq \|f\|_\infty \quad \text{and} \quad \tau(a) = f(\tau), \quad \tau \in X^\omega. 
    \end{equation}
    If $f$ is positive, then we may assume $a \geq 0$.

\label{Thm:WCPoU} 
Let $(\mathcal M,X)$ be a
factorial tracially complete $C^*$-algebra. Let $\delta>0$ and $S\subset\mathcal M^\omega$ be $\|\cdot\|_{2,X^\omega}$-separable.  Suppose $a_1,\dots,a_N\in \mathcal M_+$ satisfy
\begin{equation}
\sup_{\tau\in X}\min_{1\leq n\leq N}\tau(a_n)<\delta.
\end{equation}
Then there exists positive contractions $e_1,\dots,e_N\in \mathcal M^\omega_+\cap \mathcal S'$ with $\sum_{n=1}^Ne_n=1$ and 
\begin{equation}\label{WCPoU:MainEquation}
\tau(a_ne_n)\leq \delta \tau(e_n),\quad n=1,\dots,N.
\end{equation}

\label{def:CondExp} 
Let $\mathcal{M}$ be a $C^*$-algebra. 
For a finite-dimensional $C^*$-algebra $F$ and a $^*$-homomorphism $\varphi\colon F \to \mathcal{M}$, we use $E_{\varphi(F)'}$ to denote the canonical conditional expectation $\mathcal{M} \to \mathcal{M} \cap \varphi(F)'$; this is given by
\begin{equation} \begin{split} 
\label{eq:CondExp}
E_{\varphi(F)'}(a) &\coloneqq \int_{u \in \mathcal U(F)} \varphi(u)a\varphi(u)^*\,du + (1-\varphi(1_{F})) a (1-\varphi(1_{F})).
\end{split} 
\end{equation} 
The integral part in the above is equal to an average over any finite subgroup of the unitary group of $F$ that generates $F$. If $F=M_k$ then the integral part is equal to $\frac1k \sum_{i,j} \varphi(e_{ij})a\varphi(e_{ji})$.

\label{rem:cond_exp} \hfill
\begin{enumerate} 
\item 
\label{rem:con_exp_1} 
The conditional expectation $E_{\varphi(F)'}$ defined in Definition~\ref{def:CondExp} is trace-preserving. Indeed, for any $\tau \in X$ and $a\in \mathcal{M}$, we have 
\begin{equation} 
\begin{split} 
\tau (E_{\varphi(F)'} (a)) &= \int_{u\in \mathcal{U}(M_{d})} \tau (\varphi(u) a \varphi(u)^{*}) du + \tau ((1-\varphi(1_{F}))a)\\ 
&= \tau (\varphi(1_{k})a) + \tau ((1-\varphi(1_{F}))a) = \tau (a). 
\end{split} 
\end{equation} 
\item 
\label{rem:con_exp_2} 
Let $\mathcal{M}$ be a $C^*$-algebra and let $\varphi: F\rightarrow \mathcal{M}$ be a unital $^*$-homomorphism from the finite-dimensional algebra $F$, then for any positive element $a\in \mathcal{M}$, 
\begin{equation} 
\label{cond_exp_bound} 
a \leq C_F E_{\varphi(F)'} (a), 
\end{equation} 
for a constant $C_F$ depending only on $F$.
Namely, one can take $C_F$ to be the size of a finite subgroup $G_F$ of unitaries which generate $F$ as a $C^*$-algebra, and then we have $E_{\varphi(F)'} = \frac1{C_F} \sum_{u \in G_F} \varphi(u)a\varphi(u)^*$.
\end{enumerate}

\label{Lem:RelCom} 
Let $B$ be a unital $C^*$-algebra and $F$ a finite-dimensional $C^*$-subalgebra containing the unit of $B$.  Let $r_1,\dots,r_S$ be the minimal central projections of $F$ (i.e.\ $F\cong \oplus_{s=1}^{S} Fr_{s}$) and let $e_1,\dots,e_S$ be minimal projections in $F$ with $e_s\leq r_s$. Then
\begin{equation}
B\cap F'=\oplus_{s=1}^S (r_sBr_s \cap (Fr_s)')\cong \oplus_{s=1}^S e_sBe_s.
\end{equation}
In particular if $B$ has real rank zero so too does $B\cap F'$.

By Proposition~\ref{strict_compa_A_ultrap}, $A^\omega$ has strict comparison with respect to $\overline{T_\omega(A)}$.
We show divisibility of the unit of $A^\omega$, only using almost divisibility of the Cuntz class of a strictly positive element of $A$.
Fix $n \in \mathbb{N}$ and $\epsilon>0$.
We will find a c.p.c.\ order zero map $\varphi\colon M_n \to A$ such that $\tau(\varphi(1_n))>1-\epsilon$ for all $\tau$.
By Kirchberg's epsilon test, it then follows that there exists a c.p.c.\ order zero map $\varphi\colon M_n \to A^\omega$ such that $\tau(\varphi(1_n))=1$ for all $\tau \in T_\omega(A)$. This $\varphi$ must be unital and so is a $^*$-homomorphism by \cite[Proposition 1.4]{BBSTWW}. Therefore, $1_{A^\omega}$ is divisible.

Let $h\in A_+$ be a strictly positive element. Then $d_\tau(h)=1$ for all $\tau \in T(A)$.
By a standard application of Dini's theorem,\footnote{Note that $(\tau \mapsto d_\tau((b-1/n)_+))_{n=1}^\infty$ is an increasing sequences of lower-semicontinuous functions converging pointwise to the continuous function 1 on the compact set $T(A)$.} there exists $\delta>0$ such that 
\begin{equation} \label{eq:deltaChoice}
d_\tau((h-\delta)_+)>1-\frac{1}{3}\epsilon, \quad \tau\in T(A). 
\end{equation}
Let $k\in\mathbb{N}$ be such that 
\begin{equation}\label{eq:kChoice1} 
    \frac1{nk+1}<\frac{1}{3}\epsilon.
\end{equation}
By almost divisibility of $[h]$, there exists $[b]\in \text{Cu}(A)$ such that
\begin{equation}\begin{split}
(nk)[b] &\leq [h] \label{eq:divide_nk-1},
\shortintertext{and}
[(h-\tfrac{1}{2}\delta)_+] &\leq (nk+1)[b].  
\end{split}\end{equation} 
Since $[(h-\delta)_+] \ll [(h-\tfrac{1}{2}\delta)_+]$, there exists $\eta > 0$ such that 
\begin{equation} 
\label{upper_bound_decrease} 
[(h-\delta)_+] \leq (nk+1) [(b-\eta)_{+}]. 
\end{equation}
By \cite[Lemma 2.4]{RR_divisible},\footnote{Note that there is a 1-1 correspondence between c.p.c.\ order zero maps $M_n \rightarrow B$ and $^*$-homomorphisms $C_0(0,1] \otimes M_n \rightarrow B$ for any $C^*$-algebra $B$ by \cite[Corollary 4.1]{WZ:Munster}.} it follows from \eqref{eq:divide_nk-1} that there exists a c.p.c.\ order zero map $\psi\colon M_{n}\rightarrow \overline{h(A\otimes\mathcal{K})h}\subseteq A$ (as $h\in A$) such that 
\begin{equation}\label{eq:kChoice}[\psi(e_{11})] = k[(b-\eta)_{+}].\end{equation}
Let $\tau \in T(A)$. Then 
\begin{equation} \label{eq:d-tau-estimate-1}\begin{array}{rcl}
d_{\tau} (\psi(1_{n})) &=& nd_\tau(\psi(e_{11})) \\
&\stackrel{\eqref{eq:kChoice}}{=}& nk d_{\tau}((b-\eta)_{+}) \\
&\stackrel{\eqref{upper_bound_decrease}}\geq& \frac{nk}{nk+ 1} d_{\tau}((h-\delta)_+) \\
&\stackrel{\eqref{eq:deltaChoice},\eqref{eq:kChoice1}}\geq& 1-\frac{2}{3}\epsilon. 
\end{array}\end{equation} 

Applying Dini's theorem to the increasing sequence of continuous functions $f_m\colon T(A) \to \mathbb{R}$ given by $f_m(\tau) = \tau(\psi(1_n)^{1/m})$, there exists $m \in \mathbb{N}$ such that $\tau(\psi(1_n)^{1/m})\geq 1-\epsilon$
for all $\tau\in T(A)$.
Then the c.p.c.\ order zero map $\varphi\coloneqq \psi^{1/m}$ (defined via the order zero functional calculus of \cite{WZ:Munster}) has the required properties.

\label{def:classification-of-projections}
Let $(\mathcal{M}, X)$ be a II$_1$ tracially complete $C^*$-algebra.\footnote{We restrict to the II$_1$ setting because existence of projections should be defined differently outside the II$_1$ setting.} Then 
\begin{enumerate} 
\item $(\mathcal{M}, X)$ has \emph{comparison of projections} if, for any two projections $p, q \in \mathcal{M}$ such that $\tau(p) \leq \tau (q)$ for all $\tau \in X$, we have $p \precsim q$; 
\item $(\mathcal{M}, X)$ has \emph{existence of projections} if for any $f\in \textrm{Aff}(X)$ with $0\leq f \leq 1$, there exists a projection $p\in \mathcal{M}$ such that $\tau (p) = f(\tau)$ for all $\tau \in X$; 
\item $(\mathcal{M}, X)$ has \emph{classification of projections} if both (i) and (ii) hold. 
\end{enumerate} 
Occasionally, we will use a much weaker version of (ii), and say that \emph{all constant trace projections exist} in $(\mathcal{M},X)$ when, for all $0\leq\gamma\leq1$, there exists a projection $p\in \mathcal M$ with $\tau(p)=\gamma$ for all $\tau\in X$.

\label{Prop:MvN}
    Let $(\mathcal M,X)$ be a tracially complete $C^*$-algebra with comparison of projections.
    Suppose $p,q \in\mathcal{M}$ are projections with $\tau(p) = \tau(q)$ for all $\tau \in X$, then there exists a unitary $u\in\mathcal{M}$ with $upu^*=q$.

\label{Class:FD}
    Let $(\mathcal M,X)$ be a II$_1$ tracially complete $C^*$-algebra with classification of projections.  Then $(\mathcal M,X)$ has classification of  finite-dimensional subalgebras, in the sense that for a finite-dimensional $C^*$-algebra $F$:
    \begin{enumerate}
        \item \label{it:ClassFDExistence}
        given a projection $p\in \mathcal{M}$ and continuous affine map $\alpha\colon X\to T_{\leq 1}(F)$ such that $\alpha(\tau)(1_F) \leq \tau(p)$ for all $\tau \in X$, there exists a $^*$-homomorphism $\theta\colon F\to p\mathcal Mp$ with $\tau \circ \theta=\alpha (\tau)$ for all $\tau\in X$; if $\alpha(\tau)(1_F)=\tau(p)$ for all $\tau \in X$ then $\theta(1_F)=p$; 
        \item \label{it:ClassFDUniqueness}
        two $^*$-homomorphisms $\varphi,\psi\colon F\to\mathcal M$ are unitarily equivalent if and only if $\tau\circ\varphi=\tau\circ\psi$ for all $\tau\in X$.
    \end{enumerate}

\label{S4.2:Prop}
    Let $(\mathcal{M},X)$ be a II$_1$ factorial tracially complete $C^*$-algebra such that $\mathcal M^\omega$ has strict comparison with respect to $X^\omega$ and $\mathcal{M}^\omega$ has a divisible unit, i.e.\ $M_n\hookrightarrow \mathcal{M}^\omega$ unitally for all $n\in\mathbb N$.
    Then:
    \begin{enumerate}
        \item\label{it:classif-proj-omega} $\mathcal{M}^\omega$ has classification of projections, and hence also of finite-dimensional subalgebras;
        \item\label{it:rr0-omega} $\mathcal{M}^\omega$ has real rank zero;
        \item\label{it:sr1-omega} $\mathcal{M}^\omega$ has stable rank one;
        \item\label{it:pure-omega} $\mathcal{M}^\omega$ is pure.
    \end{enumerate}

Let $p, q \in \mathcal{M}^\omega$ be projections such that $\tau(p) \leq \tau(q)$ for all $\tau\in X^\omega$.
Let $n\in\mathbb N$. As $\mathcal{M}^\omega$ has divisible unit, there exists a projection $r\in \mathcal{M}^\omega$ of constant trace $\tfrac{1}{n}$.  
Then, in $M_2(\mathcal{M}^\omega)$, we have
\begin{equation}
\tau(p\oplus 0)<\tau(q\oplus r)
\end{equation}
for every $\tau\in X_2^\omega$. Since $M_2(\mathcal{M}^\omega)$ has strict comparison with respect to $X^\omega_2$, there exists $v\in M_2(\mathcal{M}^\omega)$ with $v^*v=p \oplus 0$ and $vv^*\leq q\oplus r$.  Let $w \in \mathcal M_2^\omega$ be such that  $w \oplus 0 =(q \oplus 0) v(p \oplus 0) \in\mathcal M^\omega$. Then $qw=w$ and
\begin{equation}
    \|w^*w-p\|_{2,X^\omega}^2
    =2\|v^*(q\oplus 0)v-v^*(q\oplus r)v\|_{2,X^\omega_2}^2=\frac{2}{n}.
\end{equation}
Kirchberg's epsilon test provides $w\in \mathcal{M}^\omega$ with $w^*w=p$ and $qw=w$. Therefore, $p\precsim q$.

Let $f \in \mathrm{Aff}(X)$ be such that $0 \leq f \leq 1$.  Since $\mathcal{M}^\omega$ has strict comparison with respect to $X^\omega$, Proposition~\ref{prop:computing-traces} gives $T(\mathcal{M}^\omega)=X^\omega$. By Proposition \ref{prop:CP-ultrapowers}, there exists a positive contraction $a\in \mathcal{M}^\omega$  with $\tau(a)=f(\tau)$ for all $\tau\in T(\mathcal{M}^\omega)$.

Let $n\in\mathbb N$. We'll now produce $p\in \mathcal{M}^{\omega}$ such that $\|p-p^2\|_{2,X^\omega}^2 \leq \frac{1}{2^n}$ and $\tau (p) = \tau (a)$ for any $\tau\in X^\omega$.
Once this is done, Kirchberg's epsilon test produces a projection $p\in\mathcal{M}^\omega$ with $\tau(p)=f(\tau)$ for all $\tau\in X^\omega$, as required.

Using divisibility of the unit, fix a unital embedding $\iota\colon M_{n} \to \mathcal{M}^\omega$ and set
\begin{equation} b \coloneqq E_{\iota(M_{2^n})'}(a)\in \mathcal{M}^\omega\cap\iota(M_{n})' \end{equation}
where $E_{\iota(M_{n})'}$ is the canonical conditional expectation from
Definition~\ref{def:CondExp}.
Then $b$ is a positive contraction such that $\tau(b)=\tau(a)$ for all $\tau\in X^\omega$ by Remark~\ref{rem:cond_exp}\ref{rem:con_exp_1}.

The rest of this proof closely follows the ``tracial projectionisation'' argument of \cite[Lemma~2.4]{CETWW}.
Next, define functions $g_1,\dots,g_n \in C([0,1])$ by requiring that
$g_i|_{[0,\frac{i-1}{n}]} = 0$, $g_i|_{[\frac{i}{n},1]} = 1$, and $g_i$ is affine on $[\frac{i-1}{n},\frac{i}{n}]$. Note that 
\begin{equation} 
\label{eq:Projectionization2}
\mathrm{id}_{[0,1]} = \frac{1}{n} \sum_{i=1}^n g_i, \quad \text{and} 
\end{equation} 
\begin{equation}  
\label{eq:Projectionization3} 
0\leq \sum_{i=1}^n (g_i-g_i^2) \leq 1_{C([0,1])}.
\end{equation}
Then define
\begin{equation}\label{eq:def-p}
    p\coloneqq \sum_{i=1}^n \iota(e_{ii})g_i(b),
\end{equation}
which is a positive contraction by orthogonality of the $e_{ii}$.

For $\tau \in X^\omega$, since $M_n$ has unique trace, $\tau(g_i(b)\iota(\cdot))$ is a scalar multiple of this trace, and so
\begin{equation}\label{eq:Projectionization1}
    \tau(g_i(b)\iota(e_{ii}))=\frac{\tau(g_i(b))}{n}.
\end{equation}
Thus we have
\begin{equation}
    \tau(p) \stackrel{\eqref{eq:def-p}}{=} \tau \left(\sum_{i=1}^{n} \iota(e_{ii})g_{i}(b)\right) \stackrel{\eqref{eq:Projectionization1}}= \sum_{i=1}^{n} \frac{1}{n}\tau (g_{i}(b))
\stackrel{\eqref{eq:Projectionization2}}= \tau(b),\quad \tau\in X^\omega.
\end{equation}
Moreover, for $\tau \in X^\omega$, using that the $\iota(e_{ii})$ are orthogonal and commute with $b$,
\begin{equation} \begin{array}{rcl}
\tau(p-p^2)
&=& \tau\left(\sum_{i=1}^n \iota(e_{ii})\left(g_i(b)-g_i(b)^2\right)\right) \\
&\stackrel{\eqref{eq:Projectionization1}}=& \sum_{i=1}^n \frac1N\tau\left(g_i(b)-g_i(b)^2\right) \stackrel{\eqref{eq:Projectionization3}}\leq \tfrac1n \tau(1_{\mathcal{M}^\omega}) = \tfrac1n.
\end{array}
\end{equation}
Since $p-p^2$ is a positive contraction, we get
\begin{equation} \|p-p^2\|_{2,X^\omega}^2=\sup_{\tau\in X^\omega}\tau((p-p^2)^2) \leq \sup_{\tau \in X^\omega} \tau(p-p^2) \leq \tfrac1n, 
\end{equation} as required.

Without loss of generality, we can assume that $a$ is contractive. Since $\tau \mapsto d_{\tau} (a)$ is a lower-semicontinuous function on the compact space $X^\omega$, and the function is strictly positive, there exists some $\delta > 0$ such that $d_\tau(a) > \delta$ for every $\tau\in X^\omega$. Again by compactness of $X^\omega$ and lower semicontinuity of $d_{\tau}$, there exists $\epsilon > 0$ such that $d_\tau((a-\epsilon)_{+}) > 0$ for every $\tau\in X^\omega$.

 Our objective is to obtain an increasing sequence of projections $q_1\leq q_2\leq\dots$ in $\overline{a\mathcal{M}^\omega a}$ with $\tau(q_n)\to d_\tau(a)$ for all $\tau\in X^\omega$.  Suppose this has been achieved. Then for $\tau\in X^\omega$, we have that $\pi_\tau(q_n)$ is an increasing sequence of projections in $\pi_\tau(\mathcal{M}^\omega)''$ which converge strongly to $\chi_{(0,\infty)}(\pi_\tau(a))$ and so, for all $n \in \mathbb{N}$,
 \begin{equation}  
 \tau(q_na^2)=\tau(aq_na)\leq\tau(aq_{n+1}a)=\tau(q_{n+1}a^2)
 \end{equation}
 and $\lim_{n\to\infty}\tau(q_na^2)=\tau(a^2)$. By Dini's theorem this convergence is uniform, so
 \begin{equation}
     \|q_na-a\|_{2,X^\omega}^2=\sup_{\tau\in X^\omega}\tau(a^2-q_na^2)\to 0.
 \end{equation}
 Taking $n$ large enough proves the result.

 We now construct the desired sequence.  For each $n\in \mathbb{N}$, define $f_{n}\in C([0,1])$ to be the continuous piecewise affine function, 
 \begin{equation} 
 f_{n}(t) \coloneqq 
 \begin{cases} 
 0, & t\in \left [0, \frac{\epsilon}{n+1}\right]; \\ 
 \text{affine}, & t\in \left [\frac{\epsilon}{n+1}, \frac{\epsilon}{n}\right]; \\ 
 1, & t\in \left[\frac{\epsilon}{n}, 1\right]. 
 \end{cases} 
 \end{equation} 
 Note that $f_{n}$ is an increasing sequence of positive functions converging on $[0,1]$ to $\chi_{(0,1]}$ pointwise, which implies that 
 \begin{equation} 
 \tau (f_{n}(a)) \rightarrow d_{\tau} (a), \quad \tau \in X^\omega. 
 \end{equation} 
 Moreover, for all $n \in \mathbb{N}$, we have $f_n(a)(a-\epsilon)_+ = (a-\epsilon)_+$ and
 \begin{equation} 
 \label{act_as_identity} 
 f_{n+1}(a)f_{n}(a) = f_{n}(a).
 \end{equation} 
 For each $n\in \mathbb{N}$, by the existence part of Proposition \ref{S4.2:Prop}(i), we can find a projection $r_{n}\in \mathcal{M}^{\omega}$ such that 
 \begin{equation} 
 \label{exist_proj_converg} 
 \tau(r_{n}) = \left(1-\frac{1}{n}\right) \tau (f_{n} (a))< d_{\tau}(f_{n}(a)), \quad \tau \in  X^\omega.  
 \end{equation} 
 The strict inequality above holds because $d_{\tau}(f_{n}(a)) \geq d_{\tau}( (a-\epsilon)_{+} )>0$ for any $\tau \in X^\omega$ and $n\in \mathbb{N}$ by the choice of $\epsilon$. Since $\mathcal{M}^{\omega}$ has strict comparison with respect to $X^\omega$, we have $r_{n}\precsim f_{n}(a)$ in $\mathcal M^{\omega}$. By R{\o}rdam's lemma (\cite[Theorem 2.7 (iv)]{GP_Cuntz_semi}), there exists a projection $p_{n} \in \overline{f_n(a) \mathcal{M}^\omega f_n(a)}$ such that $p_{n}\sim r_{n}$ in $\mathcal{M}^{\omega}$. In particular, we have 
 \begin{equation}\label{eq:def-pn}
 \tau (p_{n}) = \tau (r_{n}) = \left(1-\frac{1}{n}\right) \tau (f_{n} (a)), \quad \tau \in  X^\omega. 
 \end{equation} 
 Thus we obtain a sequence of projections $(p_{n})_{n}$, where $p_{n}\in \overline{f_n(a) \mathcal{M}^\omega f_n(a)}$, and $\tau (p_{n})\rightarrow d_{\tau}(a)$ for every $\tau \in X^\omega$. We next modify these to produce the required increasing sequence.

 Take $q_1 \coloneqq p_1$. Suppose $q_1 \leq q_2 \leq \cdots \leq q_n$ have been constructed with $p_{i} \sim q_{i}$ and $q_{i} \in \overline{f_i(a) \mathcal{M}^\omega f_i(a)}$ for $i\in \{1, \cdots, n\}$. Since $f_{n}(a) \leq f_{n+1}(a)$, \eqref{eq:def-pn} implies
 \begin{equation} 
 \tau (q_{n}) < \tau (p_{n+1}), \quad \tau \in  X^\omega. 
 \end{equation} 
 By strict comparison of $\mathcal{M}^{\omega}$ with respect to $X^\omega$, there exists $v\in \mathcal{M}^{\omega}$ such that $v^*v = q_n$ and $vv^* \leq p_{n+1}$. Note that $v\in \overline{f_{n+1}(a) \mathcal{M}^\omega f_{n+1}(a)}$ as $q_{n}$ and $p_{n+1}$ are both in $\overline{f_{n+1}(a) \mathcal{M}^\omega f_{n+1}(a)}$. It remains to move $p_{n+1} - vv^{*}$ beneath $f_{n+1}(a) - q_{n}$. Since $q_n \in \overline{f_{n}(a) \mathcal{M}^\omega f_{n}(a)}$ and $f_{n+1}(a)f_n(a) = f_n(a)$ (equation \eqref{act_as_identity}), we have $f_{n+1}(a) q_{n} = q_{n}$. Thus $f_{n+1}(a) - q_{n}$ is a positive element and for all $k\in \mathbb{N}$, 
 \begin{equation} 
 \label{act_identity_power} 
 (f_{n+1}(a) - q_n)^k = f_{n+1}(a)^k - q_n.
 \end{equation} 
 Hence, we have the following for any $\tau \in X^\omega$: 
 \begin{equation} 
 \begin{array}{rcl} 
 d_\tau(f_{n+1}(a) - q_n) &\stackrel{\eqref{act_identity_power}}{=}& d_\tau(f_{n+1}(a)) - \tau(q_n)\\
 &\stackrel{\eqref{eq:def-pn}}{>}& \tau(p_{n+1}) - \tau(q_n) \\
 &=&\tau(p_{n+1} - vv^*).
 \end{array} 
 \end{equation}  
 Using strict comparison of $\mathcal{M}^{\omega}$ with respect to $X^\omega$, combined with R{\o}rdam's lemma (\cite[Theorem 2.7 (iv)]{GP_Cuntz_semi}), there exists some $w\in \mathcal{M}^{\omega}$ such that 
 \begin{equation} 
 w^*w \in \overline{(f_{n+1}(a) - q_n)  \mathcal M^\omega (f_{n+1}(a) - q_n)} \subseteq \overline{f_{n+1}(a) \mathcal M^\omega f_{n+1}(a)}, 
 \end{equation} 
 and $ww^* = p_{n+1} - vv^*$. Just as above, we have $w \in \overline{f_{n+1}(a) \mathcal{M}^\omega f_{n+1}(a)}$. Since $ww^* \perp vv^*$ and $w^*w \perp q_n = v^*v$, it follows that $u = v+w \in \overline{f_{n+1}(a) \mathcal{M}^\omega f_{n+1}(a)}$ is a partial isometry with $q_n = v^*v \leq u^*u$ and $uu^* = p_{n+1}$. Then we may set $q_{n+1} = u^*u$.  By induction we get the required increasing sequence $(q_n)_{n=1}^\infty$, which proves the lemma.

Let $b \in \mathcal{M}^\omega$ be self-adjoint. Now write $b=b_+-b_-$ as the difference of its positive and negative parts  $b_{+},b_{-}\in\mathcal M^\omega_+$.  Fix $0<\epsilon<1$. We will show there is an positive contraction $p_{11}\in \mathcal M^\omega$ with
     \begin{equation}
         p_{11}b_-=0,\ \|p_{11}b_+-b_+\|_{2,X^\omega}<\epsilon\text{ and }\|p_{11}^2-p_{11}\|_{2,X^\omega}<\epsilon.
     \end{equation}
Once this is achieved, Kirchberg's epsilon test provides a projection $r\in \mathcal{M}^\omega$ with $rb_+=b_+$ and $rb_-=0$. This gives real rank zero as for any $\delta>0$, the self-adjoint element 
\begin{equation}
   h\coloneqq r(b+\delta 1_{\mathcal M^\omega})+(1-r)(b-\delta 1_{\mathcal M^\omega})
\end{equation}
is invertible with $\|h-b\|=\delta$.

To prove the claim, use divisibility of the unit to find a projection $q\in \mathcal M^\omega$ with constant trace $\tau(q)<\frac{\epsilon^2}{27}$ for all $\tau\in X^\omega$.  Applying Lemma \ref{Lemma:RealRank0IncreasingProject} to $a\coloneqq b_+\oplus q\in M_2(\mathcal M^\omega)_+$ (and noting that $M_2(\mathcal{M}^\omega)$ inherits strict comparison with respect to $X^\omega_2$ from $\mathcal{M}^\omega$), we obtain a projection 
\begin{equation}\label{e:sw:423}
p=\begin{pmatrix}p_{11}&p_{12}\\p_{21}&p_{22}\end{pmatrix}\in \overline{(b_+\oplus q)M_2(\mathcal M^\omega)(b_+\oplus q)}
\end{equation}
such that 
\begin{equation}
\|(b_+\oplus q)p- (b_+\oplus q) \|_{2,X_2^\omega}<\frac{\epsilon^2}2.
\end{equation}
Therefore, we have
\begin{equation}\begin{split}
    \|b_+p_{11}-b_+\|_{2,X^\omega}^2\leq 2\|(b_+\oplus q)p - (b_+\oplus q)\|_{2,X^\omega_2}^2< \epsilon^2,
\end{split}\end{equation}
where the factor of $2$ arises due to the rescaling of traces from $X^\omega$ to $X_2^\omega$.
It follows from \eqref{e:sw:423} that $p_{11}\in\overline{b_+\mathcal M^\omega b_+}$, $p_{12}q=p_{12}$, $qp_{21}=p_{21}$ and $p_{22}\in q\mathcal M^\omega q$. The first of these gives $p_{11}b_-=0$. The latter three give
\begin{equation}
    \|p_{12}\|_{2,X^\omega}^2,\|p_{21}\|^2_{2,X^\omega},\|p_{22}\|_{2,X^\omega}^2\leq \|q\|_{2,X^\omega}^2<\frac{\epsilon^2}{27}.
\end{equation}
Hence,
\begin{equation}
 \|p-(p_{11}\oplus 0)\|_{2,X^\omega_2}^2<\frac{3}{2}\cdot\frac{\epsilon^2}{27}=\frac{\epsilon^2}{18}. 
\end{equation}
Therefore,
\begin{equation}
    \|(p_{11}\oplus 0)-(p_{11}\oplus 0)^2\|_{2,X^\omega_2}\leq 3\|p-(p_{11}\oplus 0)\|_{2,X^\omega_2}<\frac\epsilon{\sqrt2},
\end{equation}
i.e.\ $\|p_{11}-p_{11}^2\|_{2,X^\omega}<\epsilon$, as required.

Note that the hypotheses of Proposition~\ref{S4.2:Prop} are invariant under matrix amplification, so Proposition \ref{S4.2:Prop}\ref{it:classif-proj-omega} and Proposition~\ref{Prop:MvN} immediately gives cancellation in the Murray--von Neumann semigroup $V(\mathcal{M}^\omega)$.\footnote{Indeed, suppose $n \in \mathbb{N}$ and $p, q, r \in M_n(\mathcal{M})$ are projections such that $p\oplus r\sim q\oplus r$. Let $\tau \in X^\omega_n$, and write $\tau_2\in X^\omega_{2n}$ for the corresponding normalised trace on $M_{2n}(\mathcal{M})$. Then
    \begin{equation}
        \frac{1}{2}(\tau(p)+\tau(r))=\tau_2(p\oplus r)=\tau_2(q\oplus r)=\frac{1}{2}(\tau(q)+\tau(r)),
    \end{equation}
and so $\tau(p)=\tau(q)$. By Proposition \ref{Prop:MvN}, we have $p\sim q$.} Since $\mathcal{M}^\omega$ has real rank zero by Proposition \ref{S4.2:Prop}\ref{it:rr0-omega}, it has stable rank one by Proposition~\ref{prop:RR0CancellationSR1}.

\label{prop:ETpure}
    Let $(\mathcal{N},Y)$ be a factorial tracially complete $C^*$-algebra with real rank zero such that $V(\mathcal{N})\cong \operatorname{{Aff}}(Y)_{+}$ as ordered semigroups.
    Then $\mathcal{N}$ is pure.

\label{2609_AloweromegatoA} 
    Let $A$ be a unital $C^*$-algebra and $X$ be a compact Hausdorff space. 
    If $C(X,A_\omega)$ is $K_1$-injective (respectively, $K_1$-surjective), then  $C(X,A)$ is $K_1$-injective (respectively,  $K_1$-surjective). In particular, if $A_\omega$ is $K$-stable, then $A$ is $K$-stable.

For any $C^*$-algebra $B$, we write $\iota_B:B \rightarrow B_\omega$ for the canonical inclusion of $B$ coming from constant sequences.
    Consider the canonical inclusions 
    \begin{equation}
       C(X,A) \xrightarrow{\varphi} C(X,A_\omega) \xrightarrow{\psi} C(X,A)_\omega,
    \end{equation}
    where $\varphi = \mathrm{id}_{C(X)}\otimes \iota_{A}$, 
    and $\psi$ determined on elementary tensors by 
    $\psi(f \otimes (a_n)_{n=1}^{\infty}) = (f \otimes a_n)_{n=1}^{\infty}$ for every $f \in C(X)$ and $(a_n)_{n=1}^{\infty} \in A_\omega$.\footnote{We are identifying $C(X,A_\omega) = C(X) \otimes A_\omega = C(X) \otimes_{\mathrm{max}} A_\omega$. The map $\psi$ is well-defined on the maximal tensor product as $C(X)$ and $A_\omega$ are commuting subalgebras of $C(X,A)_\omega$.}
    Then $\psi \circ \varphi = \iota_{C(X,A)}$. 

    Hereinafter, set $D \coloneqq C(X,A)$ for brevity.
     We first observe that if $u_{n}$ and $v_{n}$ are unitaries in $U_{d}(D)$ for some $d$, such that $u = (u_{n})_{n=1}^{\infty}$ and $v = (v_{n})_{n=1}^{\infty}$ are homotopic in $U_{d}(D_{\omega})$, then 
    \begin{equation} 
    \label{homotopy_coordinatewise} 
    \{n\in \mathbb{N}: u_{n}\sim_{h} v_{n}\text{ in }U_{d}(D) \}\in \omega. 
    \end{equation}
    Indeed, $uv^{*}$ is homotopic to $1$ and thus there are self-adjoints $h_1,\dots, h_k \in M_{d}(D_{\omega})$ such that $uv^{*} = e^{ih_1} \cdots e^{ih_k}$. Take representative sequences of self-adjoints $(h_{i}(n))_{n=1}^{\infty}$ of $h_{i}$ for each $i\in \{1, \dots, k\}$. Then 
    \begin{equation} 
    (u_{n}v_{n}^{*})_{n=1}^{\infty} = (e^{ih_{1}(n)}\cdots e^{ih_{k}(n)})_{n=1}^{\infty} 
    \end{equation} 
    in $U_d (D_{\omega})$, which implies \eqref{homotopy_coordinatewise} as unitaries that are close in norm are homotopic.  

    Suppose $C(X, A_{\omega})$ is $K_{1}$-injective. Take a unitary $u\in D$ with $[u]_{1} = 0$. Then $[\varphi(u)]_1 = 0 \in K_1(C(X,A_\omega))$, which implies that $\varphi(u) \sim_{h} 1$ in $U(C(X,A_\omega))$ by its $K_{1}$-injectivity. Applying $\psi$ gives $\iota_{D}(u) \sim_{h} 1$ in $U(D_{\omega})$ and by the observation above, we conclude that $u \sim_{h} 1$ in the unitary group of $D$. 

    Suppose that $C(X, A_{\omega})$ is $K_{1}$-surjective. Take some $x \in K_1(D)$ and $u\in U_{d}(D)$ for some $d$ such that $[u]_{1} = x \in K_{1}(D)$. By $K_{1}$-surjectivity of $C(X, A_{\omega})$, there exists some unitary $v\in C(X, A_{\omega})$ such that $K_{1}(\varphi)(x) = [v]_{1}\in K_{1}(C(X, A_{\omega}))$. Then $[\iota_{D}(u)]_{1} = K_{1}(\psi\circ \varphi)(x)  = [\psi(v)]_{1} \in K_{1}(D_{\omega})$. There exists $m\geq d$ such that 
    \begin{equation} 
    \iota_{D}(u) \oplus 1^{\oplus (m-d)} \sim_{h} \psi (v)\oplus 1^{\oplus (m-1)}\quad \text{in } U_{m}(D_{\omega}). 
    \end{equation} 
    Choosing a unitary lift $(v_{n})_{n=1}^{\infty} \in \ell^{\infty}(D)$ of $\psi(v)$. 
    By the observation above, for some $n_{0}\in \mathbb{N}$, $u \oplus 1^{\oplus (m-d)} \sim_{h} v_{n_{0}}\oplus 1^{\oplus (m-1)}$ in $U_{m}(D)$, and thus $[v_{n_{0}}]_{1} = x \in K_{1}(D)$. 

    For the second part, if $A_{\omega}$ is $K$-stable, then $C(S^{n}, M_{m}(A_{\omega})) \cong C(S^{n}, M_{m}(A)_{\omega})$ is $K_{1}$-bijective for all $n \geq 0$ and $m\geq 1$. Hence by the first part of the proof,  $C(S^{n}, M_{m}(A))$ is $K_{1}$-bijective for all $n \geq 0$ and $m\geq 1$. Therefore, $A$ is $K$-stable.

\label{prop:proj-approx-classif}
    Let $(\mathcal M, X)$ be a II$_1$ factorial tracially complete $C^*$-algebra such that $\mathcal M^\omega$ has strict comparison with respect to $X^\omega$ and $\mathcal M^\omega$ has divisible unit.
    \begin{enumerate}
        \item\label{it:proj-approx-unique} For all $\epsilon > 0$, there is $\delta > 0$ such that if $p, q \in \mathcal M$ are positive contractions with 
        \begin{equation}\label{eq:proj-approx-unique-input}
            \|p^2 - p \|_{2, X} < \delta, \quad \|q^2 - q \|_{2, X} < \delta, \quad \text{and} \quad \sup_{\tau \in X} |\tau(p) - \tau(q)| < \delta,
        \end{equation}
        then there is a unitary $u \in \mathcal M$ such that 
        \begin{equation}\label{eq:proj-approx-unique-output}
            \|u pu^* - q \|_{2, X} < \epsilon.
        \end{equation}
         \item\label{it:proj-approx-exist} For all $f \in \mathrm{Aff}(X)$ with $0 \leq f \leq 1$ and $\delta > 0$, there is a positive contraction $p \in \mathcal M$ such that 
        \begin{equation}\label{eq:proj-approx-exist}
            \|p^2 - p \|_{2, X} < \delta \quad \text{and} \quad \sup_{\tau \in X} |\tau(p) - f(\tau)| < \delta.
        \end{equation}
    \end{enumerate}

Suppose \ref{it:proj-approx-unique} fails for some $\epsilon > 0$.  For each $n \in \mathbb N$, let $\delta_n = 1/n$ and choose positive contractions $p_n, q_n \in \mathcal M$ as in \eqref{eq:proj-approx-unique-input} such that there is no unitary $u_n \in \mathcal M$ as in \eqref{eq:proj-approx-unique-output}.     
    The sequences $(p_n)_{n=1}^\infty$ and $(q_n)_{n=1}^\infty$ in $\mathcal M$ 
    define projections $p, q \in \mathcal M^{\omega}$ with $\tau(p) = \tau(q)$ for all $\tau \in X^\omega$.  
    Hence by Proposition~\ref{S4.2:Prop}\ref{it:classif-proj-omega}, $p$ and $q$ are unitarily equivalent.  Since $\mathcal{M}^\omega$ has stable rank one by Proposition \ref{S4.2:Prop}\ref{it:rr0-omega}, by Theorem~\ref{thm:sr1facts}\ref{it:BrownTrick} (due to L.\ Brown), there is a unitary $u \in U(\mathcal M^\omega)$ in the path component of $1_{\mathcal M^\omega}$ such that $upu^* = q$.  Since $u$ is in the path component of $1_\mathcal{M^\omega}$, there is a sequence $(u_n)_{n=1}^\infty$ of unitaries in $\mathcal{M}$ lifting $u$ (see Proposition~\ref{Prop:LiftingPathComponent}).  Then
    \begin{equation}
        \lim_{n \rightarrow\omega} \|u_n p_n u_n^* - q_n \|_{2, X} = 0.
    \end{equation}
    This is a contradiction, proving \ref{it:proj-approx-unique}.

    For \ref{it:proj-approx-exist}, Proposition~\ref{S4.2:Prop}\ref{it:classif-proj-omega} implies there is a projection $p \in \mathcal M^\omega$ such that $\tau(p) = f(\tau|_\mathcal M)$ for all $\tau \in X^\omega$.  Let $(p_n)_{n=1}^\infty \subseteq \mathcal M$ be a sequence of positive contractions lifting $p$.  Then
    \begin{equation}
        \lim_{n \rightarrow \omega} \|p_n^2 - p_n \|_{2, X} = 0 \quad \text{and} \quad \lim_{n \rightarrow \omega} \sup_{\tau \in X} | \tau(p_n) - f(\tau) | = 0.
    \end{equation}
    For large enough $n \in \mathbb N$, $p_n \in \mathcal M$ satisfies \eqref{eq:proj-approx-exist}.

Fix $f \in \mathrm{Aff}(X)$ with $0 \leq f \leq 1$,  let $(\epsilon_n)_{n=1}^\infty \subseteq (0, \infty)$ be such that $\sum_{n=1}^\infty \epsilon_n < \infty$, and for each $n \in \mathbb N$, let $\delta_n \in (0,\delta_{n-1})$ be given by applying Proposition~\ref{prop:proj-approx-classif}\ref{it:proj-approx-unique} to $\epsilon_n$ and assume $\delta_n \rightarrow 0$.  Apply Proposition~\ref{prop:proj-approx-classif}\ref{it:proj-approx-exist} to find a positive contraction $p_n \in M$ such that 
    \begin{equation}
        \|p_n^2 - p_n\|_{2, X} < \delta_n/2 \quad \text{and} \quad \sup_{\tau \in X} | \tau(p_n) - f(\tau)| < \delta_n / 2.
    \end{equation}
    Then we have
    \begin{equation}
        \|p_n^2 - p_n\|_{2,X} < \delta_n,\ \|p_{n+1}^2 - p_{n+1}\|_{2,X} < \delta_n,\ \text{and}\ \sup_{\tau \in X} |\tau(p_n) - \tau(p_{n+1})| < \delta_n.
    \end{equation}
    By Proposition~\ref{prop:proj-approx-classif}\ref{it:proj-approx-unique} there are unitaries $v_n \in U(\mathcal M)$ such that $\|v_n p_n v_n^* - p_{n+1}\|_{2, X} < \epsilon_n$.  Define a sequence of projections by
    \begin{equation}
        q_n \coloneqq v_1^* \cdots v_{n-1}^* p_n v_{n-1} \cdots v_1 \in \mathcal M,
    \end{equation}
    so that all $n \in \mathbb N$,
    \begin{equation}
        \|q_n - q_{n+1} \|_{2, X} < \epsilon_n,\ \|q_n^2 - q_n\|_{2, X} < \delta_n/2,\ \text{and}\ \sup_{\tau \in X} |\tau(q_n) - \tau(f)| < \delta_n/2.
    \end{equation}
    Then the sequence $(q_n)_{n=1}^\infty$ is $\|\,\cdot\,\|_{2, X}$-Cauchy, and the limit $p \in \mathcal M$ is a projection with $\tau(p) = f(\tau)$ for all $\tau \in X$.

\label{lem:proj-unique-induction}
    Let $(\mathcal{M},X)$ be a II$_1$ factorial tracially complete $C^*$-algebra such that $\mathcal{M}^\omega$ has strict comparison with respect to $X^\omega$ and $\mathcal{M}^\omega$ has divisible unit.  Suppose $p, q, r_1, r_2 \in \mathcal M$ are projections such that $\tau(p) = \tau(q)$ for all $\tau \in X$, $p, q \leq r_1 \leq r_2$, and $r_1$ and $r_2$ have constant trace $t_{1}$ and $t_{2}$ with $t_{2} > t_{1} > 0$. 
    Then for every $\epsilon > 0$, there is a unitary $u \in r_2 \mathcal M r_2$ such that 
    \begin{equation}
        \|u p u^* - q\|_{2, X} < \epsilon \quad \text{and} \quad \| u - r_2 \|_{2, X} < 2 \|p - q\|_{2, X} + 2 \sqrt{ (t_2 - t_1)}  
        + \epsilon.
    \end{equation}

By Proposition~\ref{S4.2:Prop}\ref{it:classif-proj-omega}, $(\mathcal M^\omega, X^\omega)$ has classification of projections, so $p \sim q$ and $r_1 - p \sim r_1 - q$ in $\mathcal M^\omega$.  It follows that $p$ and $q$ are unitarily equivalent in the corner $r_1 \mathcal M^\omega r_1$.  Let $v \in r_1 \mathcal M^\omega r_1$ be a unitary with $v p v^* = q$.  Define a contraction by
    \begin{equation}
        a \coloneqq pvp + (r_1 - p)v (r_1 - p) \in r_1 \mathcal M^\omega r_1 \cap \{p\}',
    \end{equation}
so that
\begin{equation}\label{E5.13}
    \begin{split}
        \|a - v\|_{2, X^\omega}^2 
        &= \| pvp - pv + (r_1 - p) v (r_1 - p) - (r_1 - p)v \|_{2, X^{\omega}}^2 \\
        &= \|pvp - pv\|_{2, X^\omega}^2 + \|(r_1 - p)v (r_1 - p) - (r_1-p)v\|_{2, X^\omega}^2 \\
        &= \| p(q - p)\|_{2, X}^2 + \|(r_1-p)(p -q)\|_{2, X}^2 \\
        &=\|r_1 (p - q) \|_{2, X}^2 \\
        &= \|p - q\|_{2, X}^2
    \end{split}
    \end{equation}


    Note that $r_1\mathcal M^\omega r_1 \cap \{p\}'$ is a direct sum of two corners of $\mathcal M^\omega$ (given by the projections $p$ and $r_1 - p$), so as noted in Section~\ref{SS:SR1}, it inherits stable rank one from $\mathcal M^\omega$ (Proposition~\ref{S4.2:Prop}\ref{it:sr1-omega}).
    Reindexing the approximate polar decompositions given by 
    Proposition \ref{it:sr1PolarDecomp} provides a unitary $w \in r_1 \mathcal M^\omega r_1 \cap \{p\}'$ such that $a=w|a|$.
    Let $\tilde{u}\coloneqq vw^*$ and note that $\tilde{u}$ is a unitary in $r_1 \mathcal M^\omega r_1$ with $\tilde{u}p\tilde{u}^* = q$.

    Calculating similarly to \eqref{E5.13}, we have
    \begin{equation}
    \begin{split}
        \|w - a \|_{2, X^\omega}^2 &= \|r_1 - |a|\|_{2, X^\omega}^2 \\
        &\leq \|r_1 - |a|^2\|_{2, X^\omega}^2 \\
        &\leq \|p - pv^*pvp \|_{2, X^\omega}^2 \\
        &\qquad + \|(r_1 - p) - (r_1 - p)v^*(r_1 - p) v (r_1 - p)\|_{2, X^\omega}^2
        \\
        &= \|pv^*(q - p)v p \|_{2, X^\omega}^2 \\
        &\qquad + \|(r_1 - p)v^*(p - q) v (r_1 - p)\|_{2, X^\omega}^2
        \\
        &\leq \|pv^*(p -q) \|_{2, X^\omega}^2 + \|(r_1 - p) v^*(p -q)\|_{2, X^\omega}^2 \\
        &= \|r_1 v^*(p - q)\|_{2, X^\omega}^2 \\
        &\leq \|p-q\|_{2,X}^2.
    \end{split}
    \end{equation}
    Combining this with \eqref{E5.13} gives
    \begin{equation}
        \|\tilde{u} - r_1 \|_{2, X^\omega} = \| v - w\|_{2, X^\omega} \leq 2 \|p - q\|_{2, X}^2.
    \end{equation}

    Note that $(r_2 - r_1) \mathcal M^\omega (r_2 - r_1)$ is a full corner of $\mathcal M^\omega$ (since $t_{2} - t_{1} > 0$ and by strict comparison), and so its inclusion into $\mathcal{M}^\omega$ induces an isomorphism on $K_1$.  
    Using $K_1$-surjectivity of $(r_2-r_1)\mathcal{M}^\omega(r_2-r_1)$ from Theorem~\ref{thm:sr1facts}\ref{it:sr1Rieffel} (again using that stable rank one passes to corners; see Section \ref{SS:SR1}), there is a unitary $w_2 \in (r_2 -r_1)\mathcal M^\omega (r_2 - r_1)$ such that
    \begin{equation} 
        [r_1 + w_2 + (1 - r_2)] = [\tilde{u} + (1 - r_1)] \text{ in }K_1(\mathcal M^\omega).
    \end{equation}
    Using that $r_2 \mathcal M r_2$ is a full corner of $\mathcal M^\omega$, it follows that $u\coloneqq \tilde{u} + w_2^* \in r_2\mathcal{M}^\omega r_2$ has trivial $K_1$-class.
    Hence by $K_1$-injectivity of $r_2 \mathcal M^\omega r_2$ (again from Theorem~\ref{thm:sr1facts}\ref{it:sr1Rieffel} using stable rank one on a corner), $u$ is in the path component of the unit in $U(r_2\mathcal M^\omega r_2)$, and so it lifts to a sequence $(u_n)_{n=1}^\infty$ of unitaries in $r_2\mathcal{M} r_2$. Note that $upu^* = q$ and
    \begin{equation}
    \begin{split}
        \|u - r_2 \|_{2, X^\omega} &\leq \|\tilde{u} - r_1\|_{2, X^\omega} +   \| w_2^* - (r_2-r_1)\|_{2, X^\omega} \\
        &\leq 2\|p - q\|_{2, X} + 2 \sqrt{(t_2 - t_1)}.  
    \end{split}
    \end{equation}
    Hence the required properties are satisfied by some $u_n$.

It suffices to show uniqueness of projections in the sense that if $p, q \in \mathcal M$ and $\tau(p) = \tau(q)$, then $p$ and $q$ are Murray and von Neumann equivalent.  Indeed, if this holds and $p, q \in \mathcal M$ are such that $\tau(p) \leq \tau(q)$ for all $\tau \in X$, the existence of projections implies there is a projection $r \in \mathcal M$ such that $\tau(p) + \tau(r) = \tau(q)$, and then uniqueness of projections applied to $M_2(\mathcal M)$ implies $p \oplus r \precsim q \oplus 0$.  Hence $p \precsim q$, proving comparison of projections.  Finally, when verifying uniqueness of projections, after replacing $\mathcal M$ with $M_2(\mathcal M)$ (which shares the same hypotheses as $\mathcal{M}$) and $p$ and $q$ with $p \oplus 0$ and $q \oplus 0$ in $M_2(\mathcal M)$, we may assume there is a projection $r$ with constant trace $t< 1$ such that $p, q \leq r$. 

     Now we prove uniqueness under these additional hypotheses.  So assume $p, q, r_0 \in \mathcal M$ are projections such that $\tau(p) = \tau(q)$ for all $\tau \in X$, $p, q \leq r_0$, and $r_0$ has constant trace $t_0 < 1$.  Let $(\epsilon_n)_{n=1}^\infty \subseteq (0, \infty)$ be decreasing such that $\sum_{n=1}^\infty \epsilon_n < \infty$.  We will inductively construct an increasing sequence of projections $(r_n)_{n=1}^\infty$ in $\mathcal{M}$, where each $r_n$ has constant trace $t_n < 1$ and a sequence of normal partial isometries $(u_n)_{n=1}^\infty$ in $\mathcal M$ such that each $u_n$ is a unitary in $r_{n}\mathcal{M} r_{n}$,  
    \begin{equation}
        \|u_n p u_n^* - q \|_{2, X} < \epsilon_n, \qquad  \text{and} \qquad  \|u_{n+1} - u_n\|_{2, X} < 3 \epsilon_n.
    \end{equation}

    Let $u_0 = r_{0}$ and suppose $r_n$ and $u_n$ have been constructed.  Choose $\delta_n > 0$ such that 
    \begin{equation} 
    \label{choose_delta_n}
        t_n + \delta_n < 1 \qquad  \text{and} \qquad 2 \|u_n p u_n^* - q\|_{2, X} +  3 \sqrt{\delta_n} < 2\epsilon_n.
    \end{equation}
    Since $r_n$ has constant trace $t_n < 1$, applying the existence of projections part of Theorem \ref{thm:classif-proj} in the corner $(1-r_n) \mathcal M (1 - r_n)$, we can find a projection $r_n'$ orthogonal to $r_n$ with constant trace $\delta_n$.  Set $r_{n+1} = r_n + r_n'$ and note that this is a projection in $\mathcal M$ with constant trace $t_{n+1} = t_n + \delta_n \in (0, 1)$ and $r_n \leq r_{n+1}$.

    Note that $u_n p u_n^*$ and $q$ are projections in $\mathcal M$ which agree on trace and satisfy $u_n p u_n^*, q \leq r_n$.  By Lemma~\ref{lem:proj-unique-induction}, there is a unitary $v_{n+1}$ in the corner $r_{n+1} \mathcal M r_{n+1}$ such that
    \begin{equation} 
        \|v_{n+1} u_n p u_n^* v_{n+1}^* - q \|_{2, X} < \epsilon_{n+1}
    \end{equation} 
    and 
    \begin{equation} 
    \label{close_identity_unitary} 
        \|v_{n+1} - r_{n+1} \|_{2, X}  < 2 \|u_n p u_n^* - q \|_{2, X} + 2 \sqrt{(t_{n+1} - t_n)} + \epsilon_{n+1}  
    \end{equation} 
    Set $u_{n+1} = v_{n+1} (u_n+ r_{n+1}-r_{n})$, which is a unitary in $r_{n+1} \mathcal{M} r_{n+1}$, and note that 
    \begin{equation}
    \begin{array}{rcl}
        \|u_{n+1} - u_n \|_{2, X} &=& \| (v_{n+1}-r_{n+1}) (u_{n} + r_{n+1} -r_{n}) + r_{n+1}-r_{n}\|_{2, X} \\
        & \leq & \|v_{n+1} - r_{n+1}\|_{2, X} +  \|r_{n+1} - r_{n}\|_{2, X}\\ 
        & \stackrel{\eqref{close_identity_unitary}}< & 2 \|u_n p u_n^* - q \|_{2, X} + 2 \sqrt{\delta_{n}} + \epsilon_{n+1} + \sqrt{\delta_{n}}\\
        & \stackrel{\eqref{choose_delta_n}}< & 3\epsilon_{n}. 
    \end{array} 
    \end{equation}
    completing the induction. 

    Since $\sum_{n=1}^\infty \epsilon_n < \infty$, the sequence $(u_n)_{n=1}^\infty$ is $\|\cdot\|_{2, X}$-Cauchy.  Let $u \in \mathcal M$ denote the limit and note that $u$.  By construction $upu^* = q$.  Since each $u_n$ is a normal partial isometry whose support contains $p$,  this also holds for $u$.  Define $w = up \in \mathcal M$ and note that $w^*w = p$ and $ww^* = upu^* = q$.

\label{Prop:ClassifyToM}
Let $(\mathcal{M},X)$ be a II$_1$ factorial tracially complete $C^*$-algebra such that $\mathcal{M}^\omega$ has strict comparison with respect to $X^\omega$ and $\mathcal{M}^\omega$ has divisible unit.
    \begin{enumerate}
        \item \label{it:ExistenceToM}
        $(\mathcal{M},X)$ has classification of unital finite-dimensional subalgebras as in Proposition~\ref{Class:FD}.
        \item \label{it:LiftingToG}
        If $G$ is a finite-dimensional $C^*$-algebra, $\gamma \in [0, 1)$, and $\varphi \colon G \rightarrow \mathcal M^\omega$ is a $^*$-homomorphism such that $\varphi(1_G)$ has constant trace $\gamma$, then there is a sequence of $^*$-homomorphisms $(\varphi_n \colon G \rightarrow \mathcal M)_{n=1}^\infty$ lifting $\varphi$ such that $\varphi_n(1_G)$ has constant trace $\gamma$ for all $n \in \mathbb N$. 
    \end{enumerate}

\ref{it:ExistenceToM} follows immediately from Propositions \ref{Class:FD} and Theorem \ref{thm:classif-proj}.

    \ref{it:LiftingToG}   
    Let $p_1, \ldots, p_k \in Z(G)$ denote the minimal central projections in $G$.  For each $i = 1, \ldots, k$, lift $\varphi(p_i)$ to a sequence of positive contractions $(a_{i, n})_{n=1}^\infty \subseteq \mathcal M$. Then since
    \begin{equation}\label{eq:sumain}
        \lim_{n \rightarrow \omega} \sup_{\tau \in X} \Big| \sum_{i=1}^k \tau(a_{i, n}) - \gamma \Big| = 0,
    \end{equation}
    by rescaling, we may assume that $\sum_{i=1}^k \tau(a_{i,n}) \leq \gamma$ for all $\tau\in X$ and $n\in\mathbb N$.
    Define $f_{i,n} \in \operatorname{{Aff}} X$ for $i=1,\dots,k$ and $n\in \mathbb{N}$ by 
    \begin{equation} \begin{split}
        f_{i,n}(\tau)\coloneqq \begin{cases} \tau(a_{i,n}),\quad &i<k; \\ \gamma-\sum_{j=1}^{k-1} \tau(a_{j,n}),\quad &i=k. \end{cases}
    \end{split}\end{equation} 
    Note that for any sequence $(\tau_n)_{n=1}^\infty$ in $X$, if $\tau\in X^\omega$ is the associated limit trace, then
    \begin{equation}\label{eq:LimitTracefin} \lim_{n\to\omega} f_{i,n}(\tau_n) = \tau(p_i), \quad i=1,\dots,k. 
    \end{equation}
    (For the case $i=k$, this uses \eqref{eq:sumain}). 

    By classification of projections in $\mathcal M$ (Theorem~\ref{thm:classif-proj}), Proposition~\ref{Class:FD} provides, for each each $n \in \mathbb N$, a $^*$-homomorphism $\psi_n \colon G \rightarrow \mathcal M$ such that\footnote{An affine function $\alpha\colon T(\mathcal{M})\to T_{\leq 1}(G)$ is fully determined by the values $\alpha(\tau)(p_i)$ on the minimal central projections.}
    \begin{equation}
        \tau(\psi_n(p_i)) = f_{i,n}(\tau), \quad i = 1, \ldots, k,\ \tau \in X.
    \end{equation}
    In particular, $\tau(\psi_n(1_G)) = \gamma$ for all $\tau \in X$. 
    Define $\psi\colon G \to \mathcal{M}^\omega$ using the sequence $(\psi_n)$.
    Then using \eqref{eq:LimitTracefin} (and since limit traces are dense in $X^\omega$), it follows that $\tau(\psi(p_i))=\tau(\varphi(p_i))$ for all $\tau\in X^\omega$ and $i=1,\dots,k$.
    Therefore, $\tau \circ \psi=\tau \circ \varphi$ for all $\tau \in X^\omega$. 
    By Proposition~\ref{Class:FD}\ref{it:ClassFDUniqueness} (again using classification of projections, this time in $\mathcal{M}^\omega$ provided by Proposition~\ref{S4.2:Prop}\ref{it:classif-proj-omega}), $\psi$ and $\varphi$ are unitarily equivalent, so there exists a unitary $v \in \mathcal{M}^\omega$ such that $\mathrm{Ad}(v)\circ\psi=\varphi$.

    Note that the projection $q \coloneqq 1_{\mathcal M^\omega}  - \varphi(1_k)$ satisfies $\tau(q)  = 1 - \gamma > 0$ for all $\tau \in X^\omega$, and since $\mathcal M^\omega$ has strict comparison with respect to $X^\omega$, $q$ is a full projection.  It follows that the inclusion $q \mathcal M^\omega q \rightarrow \mathcal M^\omega$ induces an isomorphism on $K_1$.  Since $\mathcal M^\omega$ has stable rank one by Proposition~\ref{S4.2:Prop}\ref{it:sr1-omega}, so does the corner $q \mathcal M^\omega q$ (as noted in Section~\ref{SS:SR1}), and so both $\mathcal{M}^{\omega}$ and the corner are $K_1$-bijective (Theorem~\ref{thm:sr1facts}\ref{it:sr1Rieffel}).
    By $K_1$-surjectivity, there is a unitary $w \in q\mathcal M^\omega q$ such that $[w + \varphi(1_G)] = [v^*] \in K_1(\mathcal M^\omega)$.  In particular, $u = (w + \varphi(1_G))v \in \mathcal M^\omega$ satisfies $\mathrm{Ad}(u) \circ \psi = \varphi$ and $[u] = 0 \in K_1(\mathcal M^\omega)$.  By $K_1$-injectivity of $\mathcal{M}^{\omega}$, $u$ is in the path component of the identity in $\mathcal M^\omega$ and hence lifts to a sequence of unitaries $(u_n)_{n=1}^\infty \subseteq \mathcal M$ (by the standard lifting result recorded in Proposition \ref{Prop:LiftingPathComponent}).
    Setting $\varphi_n\coloneqq \mathrm{Ad}(u_n)\circ\psi_n$ completes the proof.

\label{Lem:LiftMatrix} 
Let $(\mathcal M,X)$ be a factorial tracially complete $C^*$-algebra such that $\mathcal{M}^\omega$ has comparison with respect to $X^\omega$ and $\mathcal M^\omega$ has divisible unit. 
 Let $F$ be a finite-dimensional $C^*$-algebra and $\tau \in X$. Given $\epsilon>0$ and unital $^*$-homomorphism $\tilde{\theta}\colon F\to \pi_\tau(\mathcal M)''$, there exists a unital $^*$-homomorphism $\theta\colon F\to \mathcal M$, such that for all $x\in F$ with $\|x\|\leq 1$ 
 \begin{equation} 
 \|\pi_\tau( \theta (x))- \tilde{\theta}(x)\|_{2, \tau} <\epsilon. 
 \end{equation}

Write $\mathcal N \coloneqq \pi_\tau(\mathcal M)''$. Let $\gamma\colon T(\mathcal N) \rightarrow T(\mathcal{M})$ be the continuous affine function induced by $\pi_\tau$ (i.e.\ $\gamma(\rho)\coloneqq\rho\circ\pi_\tau$ for $\rho\in T(\mathcal N)$).  By \cite[Lemma 2.10]{carrion2023tracially},  any $\rho\in T(\mathcal N)$ has that $\rho\circ\pi_\tau$ lies in the closed face $Y$ of $X$ generated by $\tau$, i.e.\ 
 $\gamma(T(\mathcal N))$ is contained in the closed face $Y$ of $X$ generated by $\tau$. In fact it equals this face as we now argue. Note first that $\gamma(T(\mathcal N))$ contains $\tau$ and is convex and compact. 
 To see that it is a face, it suffices to check that if $\rho \in T(\mathcal N)$ and $\sigma \in X$ satisfies $\lambda \sigma \leq \gamma(\rho)$ for some $\lambda>0$ then $\sigma\in \gamma(T(\mathcal N))$.
 For this, note that $\sigma$ extends by $\|\cdot\|_{2,\rho}$-continuity to a trace $\hat\sigma$ on $\pi_{\gamma(\rho)}(\mathcal{M})''$, and so $\hat\sigma \circ \pi_\rho \in T(\mathcal N)$ and $\sigma=\gamma(\hat\sigma\circ\pi_\rho)$. 
 This concludes the proof that $\gamma\colon T(\mathcal N) \to Y$ is an isomorphism.

 The unital $^*$-homomorphism $\tilde{\theta}: F\rightarrow \mathcal N$ induces a continuous affine function $\beta\colon T(\mathcal N)\to T(F)$.  By Lemma \ref{lem:aff-lift-valuesp} the composition 
 \begin{equation}
     Y\stackrel{\gamma^{-1}}{\longrightarrow}T(\mathcal N)\stackrel{\beta}{\longrightarrow}T(F)
 \end{equation}
 extends to a continuous affine map $\alpha\colon X\rightarrow T(F)$, and, as $(\mathcal M,X)$ has classification of unital finite-dimensional $C^*$-algebras by Proposition \ref{Prop:ClassifyToM}\ref{it:ExistenceToM}, $\alpha$ is realised by a unital $^*$-homomorphism $\varphi: F\rightarrow \mathcal{M}$ such that 
 \begin{equation}\label{2509_EqEx}
     \rho \circ \varphi = \alpha (\rho),\quad \rho \in T(\mathcal{M}).
 \end{equation}
 In particular, 
 \begin{equation} 
 \rho \circ \tilde{\theta} = \beta (\rho) = \alpha(\gamma(\rho)) = \alpha(\rho\circ\pi_\tau)\stackrel{\eqref{2509_EqEx}}=\rho\circ\pi_\tau\circ\varphi,\quad \rho\in T(\mathcal N).
 \end{equation} 
 By the classification of maps from finite-dimensional $C^*$-algebras into finite von Neumann algebras by traces,\footnote{This is ancient history and due to Murray and von Neumann.} there is a unitary $u\in \mathcal N$ with 
 \begin{equation}
     \tilde{\theta}(x)=u\pi_\tau(\varphi(x))u^*,\quad x\in F. \end{equation}
 By Kaplansky's density theorem, there is an unitary $v\in \mathcal M$ such that 
 \begin{equation}\|\pi_\tau(v)-u\|_{2,\tau}<\frac{1}{2}\epsilon.
 \end{equation} 
 Define $\theta\coloneqq \mathrm{Ad}(v)\circ\varphi\colon F\to \mathcal M^\omega$. Then, for $x\in F$ with $\|x\| \leq 1$, we have
\begin{equation}
 \begin{split}
     \|\pi_\tau(\theta(x))-\tilde\theta(x)\|_{2,\tau} &=\|\mathrm{Ad}(\pi_\tau(v))(\varphi(x))-\mathrm{Ad}(u)(\varphi(x))\|_{2, \tau} \\      &\leq 2\|\pi_\tau(v)-u\|_{2,\tau}\|x\| \\
     &<\epsilon,
 \end{split}
 \end{equation}
 as required.

\label{Polar}
Let $B$ be a unital $C^*$-algebra and $p,q$ be projections in $B$ such that $qpq\leq \delta q$ for some $0<\delta<1$.  Then the partial isometry $v$ in the polar decomposition of $(1-p)q$ lies in $B$ and satisfies 
\begin{equation}  
\begin{split} 
v^*v&=q,\\ vv^*&\leq (1-p),\\
\|v-q\|&\leq\delta^{1/2}.
\end{split} 
\end{equation}

By definition, $(1-p)q=v|(1-p)q|$ in $B^{**}$ and $v^*v \leq q$. By hypothesis 
\begin{equation}
q\geq a\coloneqq |(1-p)q|^2=q(1-p)q\geq (1-\delta)q,
\end{equation}
and therefore $a$ is invertible in $qBq$ and using $a^{-1}$ to denote this inverse, we have $q\leq a^{-1}\leq (1-\delta)^{-1}q$. Therefore $a^{-1/2}\in B$ and so $v=(1-p)qa^{-1/2}\in B$. 
Next,
\begin{equation}
v^*v =a^{-1/2}q(1-p)qa^{-1/2}=q,
\end{equation} 
while $vv^*=(1-p)qa^{-1}q(1-p)$, and so $(1-p)vv^*=vv^*$.

For the last inequality, we see that\footnote{The very last inequality is justified by
\begin{equation}
    0 \leq (1-(1-\delta)^{1/2})(1-\delta^{1/2}) = 1-(1-\delta)^{1/2}- \delta^{1/2}+ (\delta(1-\delta))^{1/2}, 
\end{equation} 
and hence
$(1-\delta)^{1/2}-1+\delta^{1/2} \leq (\delta(1-\delta))^{1/2}$.
The desired inequality follows by dividing by $(1-\delta)^{1/2}$. Though we found it easier to draw a graph. }  
\begin{equation}\begin{split} 
\|v-q\|&=\|(1-p)qa^{-1/2}-q\|\\
&\leq \|qa^{-1/2}-q\|+\|pqa^{-1/2}\|\\
&\leq 1-\frac{1}{(1-\delta)^{1/2}}+\frac{\delta^{1/2}}{(1-\delta)^{1/2}} \\
&\leq\delta^{1/2}.
\end{split}\end{equation} 
