\label{2409_LemPosiSelf} 
    Let $B$ be a $C^*$-algebra, $b\in B_+$ a positive contraction and $h\in B$  self-adjoint. Then, for every $\tau\in T(B)$, 
    \begin{equation}\|[b,h]\|_{2,\tau}^2\leq 2\tau(b^{2} h^2).\end{equation}

We have the following computation 
    \begin{equation} 
        \begin{split} 
            \|[b, h]\|_{2, \tau}^2 &= 
            \tau ((bh-hb)^{*} (bh-hb)) \\
            &= \tau (hb^{2}h - hbhb - bhbh + bh^{2}b) \\
            &= 2\tau (b^{2}h^{2}) - 2\tau(hbhb)\\ 
        \end{split}
    \end{equation} 
Since $\tau(hbhb) = \|b^{1/2}h b^{1/2}\|_{2, \tau}^{2}\geq 0$, we have $\|[b, h]\|_{2, \tau}^{2}\leq 2\tau (b^{2}h^{2})$.

\label{Pythagoras} 
    Let $r_1, \ldots, r_n$ be pairwise orthogonal projections in a unital $C^*$-algebra $A$, and suppose $x \in A$ and $y_i \in r_i Ar_i$ for $i = 1, \ldots, n$.  Write $r = \sum_{i=1}^n r_i$ and $y = \sum_{i=1}^n y_i$.  Then for all $\tau \in T(A)$,
    \begin{equation}
        \|x - (1 - r) x (1 - r) - y\|_{2, \tau}^2 \leq \sum_{i=1}^n \| x - (1 - r_i) x (1 - r_i) - y_i\|_{2, \tau}^2
    \end{equation}

On expanding and using Pythagoras with respect to the matrix block decomposition $r_1,\dots,r_n,1-r$ the right-hand side exceeds the left-hand side by
    \begin{equation}
        2\sum_{i\neq j}\|r_ixr_j\|_{2,\tau}^2\geq 0.\qedhere
    \end{equation}

\label{lem:TraceProjInCommutant} 
    Let $(\mathcal{M},X)$ be a II$_{1}$ factorial tracially complete $C^*$-algebra with classification of projections and $X$ is a Choquet simplex,  and $F\subseteq \mathcal{M}$ be a finite-dimensional unital subalgebra.
    If $q \in \mathcal{M} \cap F'$ is a projection and $h \in \operatorname{{Aff}}(X)_+$ satisfies $h(\tau) \leq \tau(q)$ for all $\tau \in X$, then there exists a projection $z\in \mathcal{M} \cap F'$ such that
    \begin{equation} z \leq q\quad\text{and}\quad \tau(z)=h(\tau),\quad \tau \in X. \end{equation}

Let $p_{1}, \dots, p_{k}$ be the minimal central projections in $F$ and note that 
\begin{equation}\label{eq:new-24}
	q = \sum_{i=1}^k q p_{i} \in \mathcal M \cap F', 
\end{equation} 
as $F$ is a unital subalgebra of $\mathcal M$. 
Since $X$ is a Choquet simplex, Corollary~\ref{cor:riesz-properties} gives that $\operatorname{{Aff}}(X)$ has Riesz decomposition, so there are continuous affine functions $h_1, \ldots, h_k \in \operatorname{{Aff}}(X)_+$ such that $h = \sum_{i=1}^k h_i$ and 
\begin{equation}\label{eq:new-25}
	0 \leq h_i(\tau) \leq \tau(q p_{i}), \quad i = 1, \ldots, k,\ \tau \in X. 
\end{equation}
	Identifying $p_{i} \mathcal M p_i \cap (F p_i)'$ with a corner of $\mathcal M$, then it also has classification of projections as this property passes to corners. 
    In particular, for each $i = 1, \dots, k$, 
    there is a projection $z_i \in p_{i} \mathcal M p_i \cap (F p_i)'$ such that $z_{i} \leq q p_i$ and
	\begin{equation}\label{eq:new-26}
		\tau(z_i) = h_i(\tau), \quad \tau \in X. 
	\end{equation}
	Set $z \coloneqq \sum_{i = 1}^k z_i \in \mathcal M \cap F'$. Note that $z$ is a projection with $z \leq q$ and $\tau(z) = h(\tau)$ for all $\tau \in X$.

\label{SmallLocalApproximations} 
	Let $(\mathcal M, X)$ be a II$_1$ factorial amenable tracially complete $C^*$-algebra such that $\mathcal M^\omega$ has strict comparison with respect to $X^\omega$ and $\mathcal M^\omega$ has divisible unit.  For all $L \in \mathbb N$, $\epsilon \in (0, 1)$, and positive contractions $x_1, \ldots, x_L \in \mathcal M$, there exist $\gamma \in (0, 1)$, a finite-dimensional $C^*$-algebra $G \subseteq \mathcal M$, and positive contractions $y_1, \ldots, y_L \in G$ such that $1_G$ has constant trace $\gamma$ and 
	\begin{equation}\label{eq:new-1}
		\|x_\ell - (1_\mathcal M - 1_G) x_\ell (1_\mathcal M - 1_G)  - y_\ell \|_{2, X} \leq \epsilon\|1_G\|_{2, X}, \quad \ell = 1, \ldots, L.
	\end{equation}

It suffices to construct a finite-dimensional $C^*$-algebra $G \subseteq \mathcal M^\omega$ and positive contractions $y_1, \ldots, y_L \in G$ such that $1_G$ has constant trace $\gamma$ and 
	\begin{equation}\label{eq:new-2}
		\|x_\ell - (1_{\mathcal{M}^\omega} - 1_G) x_\ell (1_{\mathcal{M}^\omega} - 1_G)  - y_\ell \|_{2, X^\omega} \leq \epsilon\|1_G\|_{2, X^{\omega}}, \quad \ell = 1, \ldots, L.
	\end{equation}
	Indeed, from here, Proposition \ref{Prop:ClassifyToM}\ref{it:LiftingToG} provides a sequence of $^*$-homomorphisms $(\varphi_n \colon G \rightarrow \mathcal M)_{n=1}^\infty$ lifting the inclusion $G \rightarrow \mathcal M^\omega$, such that $\varphi_n(1_G)$ has constant trace $\gamma$ for all $n \in \mathbb N$.  Then for each $\ell = 1 , \ldots, L$, 
	\begin{equation}\label{eq:new-3}
		\lim_{n \rightarrow \omega} \|x_\ell - (1_{\mathcal M} - 1_{\varphi_n(G)})x_\ell (1_{\mathcal M} - 1_{\varphi_{n}(G)}) - \varphi_{n}(y_\ell)\|_{2, X} \leq \epsilon\|\varphi_{n}(G)\|_{2, X}. 
	\end{equation}
	The result will then follow (with $2 \epsilon$ in place of $\epsilon)$ by taking $G$ and $y_1, \ldots, y_L$ to be $\varphi_n(G)$ and $\varphi_n(y_1), \ldots, \varphi_n(y_L)$ for some $n \in \mathbb N$.

	With this reduction in place, define
	\begin{equation}\label{eq:new-4}
		\delta \coloneqq \frac{\epsilon^2}{28 + 8 \sqrt{2}} \qquad \text{and} \qquad \eta \coloneqq \frac{3\delta}{4L}.
	\end{equation}
	For each $\tau \in X$, note that $\pi_\tau(\mathcal M)''$ is hyperfinite by Connes' theorem (\cite{Connes:Annals}).\footnote{The hypothesis of amenability for a tracially complete $C^*$-algebra is the completely positive approximation property in the $\|\cdot\|_{2,X}$ norm.  As set out in \cite[Theorem 1.2]{carrion2023tracially}, is equivalent to amenability of the fibres $\pi_\tau(\mathcal M)''$ (passing through \cite[Theorem 4.12(i)$\Rightarrow$(iii)]{carrion2023tracially}, which, in turn, uses Brown's work on uniformly amenable traces (\cite[Theorem 3.2.2]{Brown:MAMS}) and Connes' theorem).  In the situation of most interest to us, when $A$ is nuclear and $\mathcal M=\overline{A}{}^{T(A)}$, then the fibres $\pi_\tau(\mathcal M)''$ are $\pi_\tau(A)''$, which are injective. Hence our view that this is really Connes' theorem.}  Therefore, there is a unital finite-dimensional $C^*$-algebra $\tilde F_\tau \subseteq \pi_\tau(\mathcal M)''$ and positive contractions $\tilde y_{1, \tau}, \ldots, \tilde y_{L, \tau} \in \tilde F_\tau$ such that
	\begin{equation}\label{eq:new-5}
		\|\pi_\tau(x_\ell) - \tilde y_{\ell,\tau} \|_{2, \tau} < \sqrt\eta, \quad \ell = 1, \ldots, L.
	\end{equation}
	By Lemma~\ref{Lem:LiftMatrix}, we may find a unital finite-dimensional subalgebra $F_\tau \subseteq \mathcal M$ (isomorphic to $\tilde F_\tau$) along with positive contractions $y_{1, \tau}, \ldots, y_{L, \tau} \in F_\tau$ such that 
	\begin{equation}\label{eq:new-6}
		\|x_\ell - y_{\ell, \tau} \|_{2, \tau} < \sqrt\eta, \quad \ell = 1, \ldots, L.
	\end{equation}
	By compactness of $X$, there are $N \in \mathbb N$ and $\tau_1, \ldots, \tau_N \in X$ together with open neighbourhoods $U_1, \ldots, U_N \subseteq X$ covering $X$ such that for each $n = 1, \dots, N$, 
	\begin{equation}\label{eq:new-7}
		\|x_\ell - y_{\ell, \tau_n} \|_{2, \tau} < \sqrt\eta, \quad \ell = 1, \ldots, L,\ \tau_n \in U_n.
	\end{equation}
	Define
	\begin{equation}\label{eq:new-8}
		\beta \coloneqq \frac{\delta}{2N} \qquad \text{and} \qquad \gamma \coloneqq \frac{\beta \delta}{4 \max_n C_{F_n}},
	\end{equation}
    where $C_{F_n}$ is the constant from \eqref{cond_exp_bound}.

	Further define positive elements $a_1, \ldots, a_N \in \mathcal M_+$ by
	\begin{equation}\label{eq:new-9}
		a_n \coloneqq \sum_{\ell = 1}^L (x_\ell - y_{\ell, \tau_n})^2, \quad n = 1, \ldots, N,
	\end{equation}
	and note that \eqref{eq:new-7} implies
	\begin{equation}\label{eq:new-10}
		\sup_{\tau \in X} \min_{1 \leq n \leq N} \tau(a_i) < L \eta.
	\end{equation}
	Let $T \subseteq \mathcal M$ denote the separable $C^*$-algebra generated by $F_{\tau_1} \cup \cdots \cup \mathcal F_{\tau_N}$ and apply the weak CPoU condition recalled in Theorem~\ref{Thm:WCPoU} to obtain positive contractions $e_1, \ldots, e_N \in \mathcal M^\omega \cap T'$ such that 
	\begin{equation}\label{eq:new-11}
		\tau(a_n e_n) \leq \eta L \tau(e_n), \quad n = 1, \ldots, N,\ \tau \in X^\omega,\ 
	\end{equation}

	We will inductively construct partial isometries $v_1, \ldots, v_N \in \mathcal M^{\omega}$ such that for all $n = 1, \ldots, N$, the following properties hold.
	\begin{enumerate}
		\item\label{it:new-pi-1} $v_n^* v_n$ commutes with $F_{\tau_n}$;
		\item\label{it:new-pi-2} $v_nv_n^*$ is orthogonal to the projections $v_1 v_1^*, \ldots, v_{n-1} v_{n-1}^*$;
		\item\label{it:new-pi-3} $\gamma \tau(e_n) - \beta \gamma \leq \tau(v_n^*v_n) \leq \gamma \tau(e_n)$ for all $\tau \in X^\omega$;
		\item\label{it:new-pi-4}$ \tau(a_n v_n^* v_n) \leq \delta \tau(v_n^* v_n)$ for all $\tau \in X^\omega$;
		\item\label{it:new-pi-5} $\|v_n - v_n^*v_n\| < \sqrt\delta$.
	\end{enumerate}
	To this end, fix some $n = 1, \ldots, N$ and suppose $v_1, \ldots, v_{n-1}$ have been constructed.  Define $p = \sum_{i=1}^{n-1} v_i v_i^*$ (when $n = 1$, we interpret this as $p = 0$).  For later use, we record the inequality
	\begin{equation}\label{eq:new-12}
		\tau(e_n p) \leq \tau(p) = \sum_{i=1}^{n-1} \tau(v_nv_n^*) \stackrel{\ref{it:new-pi-3}}{\leq} \sum_{i=1}^{n-1} \gamma \tau(e_i) \leq \gamma, \quad \tau \in X^\omega.
	\end{equation}

	Let $E \coloneqq E_{F_{\tau_n}'} \colon \mathcal M^\omega \rightarrow \mathcal M^\omega \cap F_{\tau_n}'$ denote the conditional expectation from Definition~\ref{def:CondExp} and define\footnote{The first term $E(a_n)$ is to control the distance from elements $x_\ell \in \mathcal M$ to the corresponding elements $y_{\ell, \tau_n} \in F_{\tau_n}$, and the second term $C_{F_n} E(p)$ controls the overlap with the projections $v_1v_1^*, \ldots, v_{n-1}v_{n-1}^*$ already constructed.}
	\begin{equation}\label{eq:new-13}
		b \coloneqq E(a_n) + C_{F_n} E(p) \in \mathcal M^\omega_{+} \cap F_{\tau_n}'.
	\end{equation}
	By Corollary~\ref{Cor:FakeSpectralProjection}, there is a projection $q \in \mathcal M^\omega \cap F_{\tau_n}' \cap \{b\}'$
	 such that
	\begin{equation}\label{eq:new-14}
	 	qb \leq \delta q \qquad \text{and} \qquad (1 -q)b \geq \delta (1 - q).  
	\end{equation}

\begin{claim}
   The following estimates hold:
	\begin{equation}\label{eq:new-15}
		\max \{0, \gamma \tau(e_n) - \gamma \beta\} \leq \min \{\tau(q), \gamma \tau(e_n) \}, \quad \tau \in X^\omega.
	\end{equation}
\end{claim}
\begin{claimproof}[Proof of Claim]
	To see this, note that the only non-trivial claim in \eqref{eq:new-15} is
	\begin{equation}\label{eq:new-16}
		\gamma \tau(e_n) - \gamma \beta \leq \tau(q), \quad \tau \in X^\omega.
	\end{equation}
	For the rest of this paragraph, let $\tau \in X^\omega$ be fixed.
	Using the second part of \eqref{eq:new-14}, 
