	\begin{split}
		\delta \tau(e_n(1 -q)) 
		&= \delta \tau(e_n^{1/2}(1-q)e_n^{1/2}) \\
		&\leq \tau(e_n^{1/2} b^{1/2} (1 - q) b^{1/2}e_n^{1/2}) \\
		&\leq \tau(e_n^{1/2} b e_n^{1/2}) \\
