	\begin{array}{rcl}
		\tau(e_n b) & \leq & \tau(e_n a_n) + C_{F_{\tau_n}} \tau(e_n p) \\
		& \stackrel{\eqref{eq:new-11},\eqref{eq:new-12}}{\leq} & L\eta \tau(e_n) + C_{F_{\tau_n}} \gamma \\
		& \stackrel{\eqref{eq:new-8}}{\leq} & L\eta \tau(e_n) + \frac{\beta\delta}4.
	\end{array}
	\end{equation}
	Combining \eqref{eq:new-17} and \eqref{eq:new-18}, we see that
	\begin{equation}\label{eq:new-19}
		\tau(e_n (1 - q)) \stackrel{\eqref{eq:new-17}}{\leq} \frac1\delta \tau(e_nb) \stackrel{\eqref{eq:new-18}}{\leq} \frac{L\eta}{\delta} \tau(e_n) + \frac{\beta}{4},
	\end{equation}
	and hence
	\begin{equation}\label{eq:new-20}
	\begin{array}{rcl}
