	\end{equation}
	This proves \eqref{eq:new-16} and hence also the claim \eqref{eq:new-15}.
    \end{claimproof}

	Since $\mathcal M^\omega$ has strict comparison with respect to $X^\omega$, Proposition~\ref{prop:computing-traces} implies $X^\omega = T(\mathcal M^\omega)$.  In particular, $X^\omega$ is a Choquet simplex.  By Corollary~\ref{cor:riesz-properties}, $X^\omega$ has Riesz interpolation, and applying this to \eqref{eq:new-15} yields a continuous affine function $h \colon X^\omega \rightarrow \mathbb R$ such that 
	\begin{equation}\label{eq:new-23}
		\max \{0, \gamma \tau(e_n) - \gamma \beta \} \leq h(\tau) \leq \min \{ \tau(q), \gamma \tau(e_n) \}, \quad \tau \in X^\omega.
	\end{equation} 
    As $\mathcal{M}^{\omega}$ has classification of projections and $X^{\omega}$ is a Choquet simplex, an application of Lemma~\ref{lem:TraceProjInCommutant} to $(\mathcal{M}^{\omega}, X^{\omega})$ and $F_{\tau_{n}}$ produces a projection $z\in \mathcal{M}^{\omega}\cap F_{\tau_{n}}'$ satisfying $z\leq q$ and $\tau (z) = h(\tau)$ for all $\tau \in X^{\omega}$. 
    In particular, \eqref{eq:new-23} implies
	\begin{equation}\label{eq:new-27}
		\gamma \tau(e_n) - \gamma \beta \leq \tau(z) \leq \gamma \tau(e_n), \quad \tau \in X^\omega.
	\end{equation}

	For $\ell = 1, \ldots, L$, since $z$ commutes with $y_{\ell, \tau_n} \in F_{n_\tau}$, we have for $\tau \in X^\omega$,
	\begin{equation}\label{eq:new-28}
	\begin{array}{rcl}
		\|[z, x_\ell]\|_{2, \tau}^2 & = & \|[z, x_\ell- y_{\ell, \tau_n}] \|_{2, \tau}^2 \\ 
		& \leq & 2 \tau(z (x_\ell - y_{\ell, \tau_n})^2) \\
		& \stackrel{\eqref{eq:new-9}}{\leq}  & 2\tau(a_n z),
	\end{array} 
	\end{equation} 
    using Lemma~\ref{2409_LemPosiSelf} and that $z$ is a projection.  Now as $z \leq q$, $z, q \in \mathcal M^\omega \cap F_{\tau_n}'$, and $E$ preserves traces on $\mathcal M^\omega$ (Remark~\ref{rem:cond_exp}\ref{rem:con_exp_1}), 
	\begin{equation}\label{eq:new-29}
		\tau(a_n z) = \tau(E(a_n) z) \leq \tau(b z) \stackrel{\eqref{eq:new-14}}{\leq} \delta \tau(z), \quad \tau \in X^\omega,
	\end{equation}
	by using \eqref{eq:new-14} at the stated point and compressing by $z$.
	Accordingly,
	\begin{equation}\label{eq:new-30}
		\|[z, x_\ell]\|_{2, \tau} \stackrel{\eqref{eq:new-28}}{\leq} \sqrt{2\tau(a_{n}z)} \stackrel{\eqref{eq:new-29}}{\leq} \sqrt{2\delta\tau(z)} = \sqrt{2\delta} \|z\|_{2, \tau}, \quad \tau \in X^\omega.
	\end{equation}

	We will now define $v_n$ by conjugating $z$ under $1 - p$.  As
	\begin{equation}\label{eq:new-31}
		qpq \stackrel{\eqref{cond_exp_bound}}{\leq} C_{F_{\tau_n}} q E(p) q \stackrel{\eqref{eq:new-13}}{\leq} qbq \stackrel{\eqref{eq:new-14}}{\leq} \delta q,
	\end{equation}
	we can compress by $z$ to get $zpz \leq \delta z$.  Then Lemma~\ref{Polar} produces a partial isometry $v_n \in \mathcal M^\omega$ such that
	\begin{equation}\label{eq:new-32}
		v_n^*v_n = z, \quad vv^* \leq 1 - p, \quad \text{and} \quad \|v_n - z\| < \sqrt\delta.
	\end{equation}
	Note that \ref{it:new-pi-1}, \ref{it:new-pi-2}, and \ref{it:new-pi-5} are immediate from \eqref{eq:new-32} by the definition of $z$ and $p$ (defined above \eqref{eq:new-27} and \eqref{eq:new-12}, respectively).  Also, \ref{it:new-pi-3} and \ref{it:new-pi-4} follow from \eqref{eq:new-27} and \eqref{eq:new-29}, respectively.  This completes the construction of $v_1, \ldots, v_N$.

    We note that \ref{it:new-pi-5} implies that for $\tau \in X^\omega$,
    \begin{equation}
    \label{eq:new-99} 
    \|v_n-v_n^*v_n\|_{2,\tau} = \|v_n-v_n^*v_n\|\,\|v_n^*v_n\|_{2,\tau} \leq \sqrt{\delta}\|v_n^*v_n\|_{2,\tau}
    \end{equation} 
	Using \ref{it:new-pi-3} and that $\sum_{n=1}^N e_n = 1_{\mathcal M^\omega}$, we have
	\begin{equation}\label{eq:new-33}
		\sum_{n=1}^N \tau(v_nv_n^*) \leq \gamma, \quad \tau \in X^\omega.	
	\end{equation}
	As $\mathcal M^\omega$ has classification of projections (Proposition~\ref{S4.2:Prop}\ref{it:classif-proj-omega}), there is a projection $d \in \mathcal M^\omega$ orthogonal to $v_1v_1^*$, \ldots, $v_N v_N^*$ such that
	\begin{equation}\label{eq:new-34}
		\tau(d) = \gamma - \sum_{n=1}^N \tau(v_n v_n^*), \quad \tau \in X^\omega.
	\end{equation} 
	For each $n \in \mathbb N$, $v_n^*v_n$ commutes with $F_{\tau_n}$ by \ref{it:new-pi-1}, so $v_n F_{\tau_n} v_n^* \subseteq \mathcal M^\omega$ is a finite-dimensional $C^*$-algebra.  Define a finite-dimensional $C^*$-algebra 
