    \begin{split}
		 & \|x_\ell - (1_{\mathcal{M}^\omega} - 1_G) x_\ell(1_{\mathcal{M}^\omega} - 1_G) - y_\ell \|_{2, \tau}^2 \\
         \leq & \sum_{n =1}^N \|x_\ell - (1_{\mathcal M^\omega} - v_n v_n^*) x_\ell (1_{\mathcal M^\omega} - v_n v_n^*) - v_ny_{\ell, \tau_n}v_n^*\|_{2, \tau}^2 \\
