	\end{split}
    \end{equation} 
    We will bound these terms separately. Starting with the last term, since $d$ is a projection, we have
    \begin{equation}
    \label{eq:new-43}
	\begin{array}{rcl}
		\|x_\ell - (1_{\mathcal M^\omega} - d) x_\ell (1_{\mathcal M^\omega} - d) \|_{2, \tau}^2 & =&  \|d x_{\ell} \|_{2, \tau}^2  + \| (1_{\mathcal M^\omega} - d)x_\ell d\|_{2, \tau}^2 \\
		&\leq& 2 \tau(d) \\ 
		&\stackrel{\eqref{eq:new-34}}{=} & 2\gamma - 2\sum_{n=1}^N \tau(v_n v_n^*) \\
		& \stackrel{\ref{it:new-pi-3}}{\leq} & 2N\beta \gamma \\
        &\stackrel{\eqref{eq:new-8}}{=}& \delta \gamma.
	\end{array}
	\end{equation}
    Next for each $n = 1, \ldots, N$, we have 
    \begin{equation}\label{eq:new-37}
		\|(x_\ell - y_{\ell, \tau_n})v_n^*v_n\|_{2, \tau}^2 = \tau((x_\ell - y_{\ell, \tau_n} )^2 v_n^*v_n) \stackrel{\eqref{eq:new-9}}{\leq} \tau(a_n v_n^* v_n) \stackrel{\ref{it:new-pi-4}}{\leq} \delta \tau(v_n^*v_n),
	\end{equation}
	and hence 
    \begin{equation}\label{eq:new-39}
	\begin{array}{rcl}
		\|[x_\ell, v_n^*v_n]\|_{2, \tau}^2 &\stackrel{\ref{it:new-pi-1}}{=} & \|[x_\ell - y_{\ell, \tau_n}, v_n^*v_n]\|_{2, \tau}^2 \\ 
		& \leq & 2 	\tau (v_{n}^{*}v_{n} (x_{\ell} - y_{\ell, \tau_{n}})^{2}) \\
        & = & 2 \|(x_\ell - y_{\ell, \tau_n})v_n^*v_n\|_{2, \tau}^2\\ 
		& \stackrel{\eqref{eq:new-37}}{\leq} & 2 \delta \tau(v_n^*v_n),
	\end{array}
	\end{equation}
    where the first inequality is true by Lemma~\ref{2409_LemPosiSelf} and that $v_{n}^{*}v_{n}$ is a projection. 
	This in turn implies that for all $n = 1, \ldots N$, and $\ell = 1, \ldots, L$,
