	\begin{array}{rcl}
		\|[x_\ell, v_n v_n^*]\|_{2, \tau} & \leq & 2 \|v_n^* v_n - v_n v_n^* \|_{2, \tau} + \|[x_\ell, v_n^* v_n]\|_{2, \tau} \\
		& \stackrel{\eqref{eq:new-39}}{\leq} &  2 (\|v_n^* v_n -v_n\|_{2,\tau}+\|v_n-v_nv_n^*\|_{2,\tau}) + \sqrt{2\delta \tau(v_n^*v_n)} \\
