    \end{equation} 
    where the first equality is true as multiplying by $v_{n}^{*}$ and $v_{n}$ on each side does not change the $2$-norm. 

    Returning to the first term in \eqref{eq:new-44}, for each $n = 1, \ldots, N$, we compute\footnote{The first inequality is best seen by thinking of a $2 \times 2$ matrix decomposition with respect to $v_n v_n^*$ and its complement.} 
    \begin{equation}\label{eq:new-46}
    \begin{array}{rcl}
        &&\hspace*{-6em}\|x_\ell - (1_{\mathcal M^\omega} - v_n v_n^*) x_\ell (1_{\mathcal M^\omega} - v_n v_n^*) - v_ny_{\ell, \tau_n}v_n^*\|_{2, \tau}^2 \\
        & = & \|[x_\ell, v_nv_n^*]\|_{2, \tau}^2 + \|v_n v_n^* x_\ell v_nv_n^* - v_n y_{\ell, \tau_n} v_n^*\|_{2, \tau}^2  \\
        &\stackrel{\eqref{eq:new-40},\eqref{eq:new-45},\ref{it:new-pi-3}}\leq& (4 + \sqrt2)^2 \delta \gamma \tau(e_n) + 9\delta \gamma \tau(e_n)  \\
