Fix a finite set $\mathcal F=\{x_1,\dots,x_L\}$ of positive contractions in $\mathcal M$ and $\epsilon>0$. 
    We consider families 
\begin{equation}
    (I,G,y)=\Big\{\bigoplus_{i\in I}G_i,(y_{1,i},\dots,y_{L,i})_{i\in I}\Big\}
\end{equation}
where:
\begin{itemize}
    \item $G_i$ are finite-dimensional subalgebras of $\mathcal M$ with pairwise orthogonal units $1_{G_i}$ which have constant trace; 
    \item $y_{\ell,i}$ are contractions in $G_i$ for $i\in I$, and $\ell=1,\dots,L$; and
    \item For $\ell=1,\dots,L$, we have
\begin{equation}\label{ZL.1}
    \Big\|x_\ell-(1-\sum_{i\in I}1_{G_i})x_{\ell}(1-\sum_{i\in I}1_{G_i})-\sum_{i\in I}y_{\ell,i}\Big\|_2^2\leq\epsilon^2\sum_{i\in I}\tau(1_{G_i}).
\end{equation}
\end{itemize}
Note that the sums in \eqref{ZL.1} converge in $\|\cdot\|_{2,X}$-norm, from the assumption that each $1_{G_i}$ has constant trace.

We order such families by saying that $(I,G,y)\leq (J,H,z)$, when there is an injection $\iota:I\to J$ such that $H_{\iota(i)}=G_i$ and $z_{\ell,\iota(i)}=y_{\ell,i}$ for all $i\in I$ and $\ell=1,\dots,L$. This says that $\bigoplus_{i\in I}G_i\subset\bigoplus_{j\in J}H_j$, and the relevant terms of the approximating elements are equal.

Given a chain, the union gives an upper bound (the approximation condition in \eqref{ZL.1} follows by continuity).  So by Zorn's lemma we can take a maximal element $(I,G,y)$.  Suppose, by way of reaching a contradiction that $\sum_{i\in I}\tau(1_{G_i})<1$. Then $q=\sum_{i\in I}1_{G_i}$ is $\|\cdot\|_{2,X}$-convergent.  We now work in the corner $(1-q)\mathcal{M}(1-q)$, and note that this corner inherits the hypotheses on $(\mathcal{M},X)$ when equipped with the traces 
\begin{equation}
    \Big\{ \frac{1}{\tau(1-q)} \tau|_{(1-q)\mathcal M(1-q)} : \tau \in X \Big\} \subseteq T((1-q)\mathcal M(1-q)).
\end{equation}  
Indeed, strict comparison of $((1-q) \mathcal M^\omega (1 -q))^\omega = (1 - q)\mathcal M^\omega (1 -q)$ follows immediately from strict comparison in $\mathcal M^\omega$, and divisibility of the unit comes from classification of finite-dimensional subalgebras of $\mathcal M^\omega$, recorded in Proposition~\ref{S4.2:Prop}\ref{it:classif-proj-omega}.


By Proposition \ref{SmallLocalApproximations}, there exists some non-zero finite-dimensional subalgebra $H$ of $(1-q)\mathcal M(1-q)$ whose unit has constant trace, and approximates $z_1,\dots,z_L\in H$ with\footnote{The trace is initially computed in the corner, and then rescaled back to $\mathcal{M}$}
\begin{equation}
    \|(1-q)x_\ell(1-q)-(1-q-1_H)x_\ell(1-q-1_H)-z_\ell\|_{2,X}\leq \epsilon\|1_H\|_{2,X}.
\end{equation}
For each $\ell=1,\dots,L$, and $\tau\in X$, we then compute (identically to Popa, and again best done by drawing some block matrix decompositions), 
\begin{equation}
    \begin{split}
        &\|x_\ell-(1-\sum_{i\in I}1_{G_i}-1_H)x_\ell(1-\sum_{i\in I}1_{G_i}-1_H)-(\sum_{i\in I}y_{\ell, i}+z_{\ell})\|_{2,\tau}^2\\
        =&\|x_\ell-(1-\sum_{i\in I}1_{G_i})x_{\ell}(1-\sum_{i\in I}1_{G_i})-\sum_{i\in I}y_{\ell, i}\|_{2, \tau}^2\\
        &+\|(1-\sum_{i\in I}1_{G_i})x_{\ell}(1-\sum_{i\in I}1_{G_i})-(1-\sum_{i\in I}1_{G_i}-1_H)x_{\ell}(1-\sum_{i\in I}1_{G_i}-1_H)-z_{\ell}\|_{2,\tau}^2\\ 
        &\leq \epsilon^2(\sum_{i\in I}\tau(1_{G_i})+\tau(1_H)).
    \end{split}
\end{equation} 
This contradicts maximality, and hence $\sum_{i\in I}\tau(G_i)=1$.  

For all $\ell=1,\dots,L$, we have
\begin{equation}
        \|x_\ell-\sum_{i\in I}y_i\|_{2,\tau}\leq\epsilon, 
\end{equation}
so we can find a finite $I_0$ such that
\begin{equation}
        \|x_\ell-\sum_{i\in I_0}y_i\|_{2,\tau}\leq2\epsilon.
\end{equation}
Taking $F=\bigoplus_{i\in I_0}G_i$, shows that $(\mathcal{M},X)$ is hyperfinite.

\label{TC:Structure:MainBody}
    Let $(\mathcal{M},X)$ be a II$_1$ factorial amenable tracially complete $C^*$-algebra. The following are equivalent:
    \begin{enumerate}
        \item $(\mathcal{M},X)$ is  hyperfinite;\label{TC:Structure:MainBody.1}
        \item $(\mathcal{M},X)$ is McDuff;\label{TC:Structure:MainBody.2}
        \item[\namedlabel{TC:Structure:MainBody.2'}{(ii$'$)}] $(\mathcal{M},X)$ has property $\Gamma$;
\item[\namedlabel{TC:Structure:MainBody.2''}{(ii$''$)}] $(\mathcal{M},X)$ has CPoU;
        \item $(\mathcal{M},X)$ has the property that $\mathcal{M}^\omega$ has strict comparison by $X^\omega$ and the unit of $\mathcal{M}^\omega$ is divisible.\label{TC:Structure:MainBody.3}
    \end{enumerate}

\label{lem:reduction-a-la-brown}
    Let $A$ be a stably finite simple separable nuclear pure $C^*$-algebra. 
    Then there is a stably finite simple separable nuclear pure $C^*$-algebra $B$ that is stably isomorphic to $A$ such that the trace space $T(B)$ is compact and $B$ has strict comparison with respect to $T(B)$. In particular, $A$ is $\mathcal{Z}$-stable if and only if $B$ is $\mathcal{Z}$-stable.

By a reindexing argument, it suffices to show that for all $\epsilon > 0$ and $n \in \mathbb N$, there is a unital embedding $\iota_n \colon M_n \rightarrow \mathcal M^\omega$ such that $\|a x - x a\|_{2, X} \leq 2\epsilon\|x\|$ for all $x \in M_n$.  Recall that $\mathcal M^\omega$ has real rank zero by \ref{S4.2:Prop}\ref{it:rr0-omega}, so there is a self-adjoint $b \in \mathcal M^\omega$ with finite spectrum such that $\|a - b\| < \epsilon$.  Then $\mathcal M^\omega \cap \{b\}'$ is a direct sum of corners of $\mathcal M$ (as in Lemma~\ref{Lem:RelCom}).  Using Proposition \ref{Class:FD} (on each corner), there is a unital embedding $\iota \colon M_n \rightarrow \mathcal M^\omega \cap \{b\}'$.  Then
    \begin{equation}
        \|[a, x]\|_{2, X} \leq \|[a, x]\| = \|[a-b,x]\| \leq 2 \|a - b\| \|x\| \leq 2 \epsilon \|x\|
    \end{equation}
    for all $x \in M_n$.

Set $Y \coloneqq \{\tau|_{\mathcal M^\omega \cap \iota(\mathcal R)'}: \tau \in X^\omega \}$ and note that $Y$ is a compact convex subset of $T(\mathcal M^\omega \cap \iota(\mathcal R)')$.  We will show $Y = T(\mathcal M^\omega \cap \iota(\mathcal R)'$ by showing that $\mathcal{M}\cap \iota(\mathcal R)'$ has strict comparison with respect to $Y$ and using Proposition~\ref{prop:computing-traces}.
    To this end, fix $n \in \mathbb N$ and $a, b \in M_n(\mathcal M^\omega \cap \iota(\mathcal R)')$ such that $d_\tau(a) < d_\tau(b)$ for all $\tau \in Y_n$. Without loss of generality we may assume $n=1$.

    Fix $\epsilon > 0$.  For each $\tau \in Y$,
    \begin{equation}
        d_\tau((a - \epsilon)_+) \leq d_\tau(a) < d_\tau(b) = \sup_{\delta > 0} d_\tau((b - \delta)_+).
    \end{equation}
    By Dini's theorem and the compactness of $Y$, there $\delta > 0$ such that 
    \begin{equation}
        d_\tau((a - \epsilon)_+) < d_\tau(b - \delta)_+), \quad \tau \in Y.
    \end{equation}
    Define a continuous function $f_\delta \colon \mathcal [0, \infty) \rightarrow [0, \infty)$ by
    \begin{equation}
        f_\delta(t) \coloneqq
        \begin{cases}
            t/ \delta, \quad &t \in [0, \delta); \\
            1, \quad &t \in [\delta, \infty).
        \end{cases}
    \end{equation}
    We'll show that for each matrix subalgebra $F \subseteq \mathcal R$, there is $v \in \mathcal M^\omega \cap \iota(F)'$ such that
    \begin{equation}\label{eq:central-traces}
        v^*v = (a - 2\epsilon)_+ \quad \text{and} \quad f_\delta(b) v = v
    \end{equation}
    Assuming this has been done, note that $\|v\|^2 \leq \|a\|$, so a reindexing argument produces $v \in \mathcal M^\omega \cap \iota(\mathcal R)'$ such that \eqref{eq:central-traces} holds.  This will imply $(a - 2 \epsilon)_+ \precsim b$ in $\mathcal M^\omega \cap \iota(\mathcal R)'$, and since $\epsilon > 0$ was arbitrary, this will imply $a \precsim b$ in $\mathcal M^\omega \cap \iota(\mathcal R)'$.

    Given $F \subseteq \mathcal R$, let $p \in F$ be a rank one projection.  Then there is an isomorphism
    \begin{equation}
        \varphi \colon \mathcal M^\omega \cap \iota(F)' \rightarrow \iota(p) \mathcal M^\omega \iota(p) \colon a \mapsto \iota(p)a,
    \end{equation}
    which satisfies 
    \begin{equation}
        \tau(\varphi(c))/\tau(\iota(p)) = \tau(c), \qquad \tau \in X^\omega,\ c \in \mathcal M^\omega \cap \iota(F)'
    \end{equation}
    Given $\tau \in X^\omega$, $\tau|_{\mathcal M^\omega \cap \iota(\mathcal R)'} \in Y$, so $d_\tau((a - \epsilon)_+) < d_\tau((b - \delta)_+)$, and therefore, $d_\tau(\varphi((a - \epsilon)_+)) < d_\tau(\varphi((b - \delta)_+))$.  As $\mathcal M^\omega$ has strict comparison with respect to tracial states, $\varphi((a- \epsilon)_+) \precsim \varphi((b- \delta)_+)$ in $\mathcal M^\omega$ and hence also in the corner $\iota(p)\mathcal M^\omega \iota(p)$.  So $(a - \epsilon)_+ \precsim (b -\delta)_+$ in $\mathcal M^\omega \cap \iota(F)'$.
    Hence there is $v \in \mathcal \mathcal M^\omega \cap \iota(F)'$
    such that
    \begin{equation}
        v^*v = (a - 2\epsilon)_+ \quad \text{and} \quad vv^* \in \overline{(b - \delta)_+(\mathcal M^\omega \cap \iota(F)') (b - \delta)_+}.        
    \end{equation}
    Then $f_\delta(b)vv^* = vv^*$ and the $C^*$-identity implies $f_\delta(b) v = v$, as required.

\label{prop:commutant-cpou}
    Let $(\mathcal{M},X)$ be a factorial tracially complete $C^*$-algebra such that $\mathcal{M}^\omega$ has strict comparison with respect to $X^\omega$. Given a unital embedding $\iota \colon \mathcal R \rightarrow \mathcal M$, 
    the tracially complete $C^*$-algebra $(\mathcal M^\omega \cap \iota(R)', X^\omega)$ is factorial and McDuff. In particular, it has CPoU (as defined in \cite[Definition~3.1]{carrion2023tracially}).

\label{lem:ETRR02.2}
    Let $(\mathcal{M},X)$ be a II$_1$ factorial tracially complete $C^*$-algebra such that $\mathcal M^\omega$ has strict comparison with respect to $X^\omega$ and $\mathcal{M}^\omega$ has a divisible unit.  Let $\epsilon > 0$ and $a, p, c \in \mathcal M$ be positive contractions with $cp = p$ and $pa = a$.  Suppose $\|p^2 - p\|_{2, X} \leq \delta$ for some $\delta \in (0, 1/4]$.  Then there is a positive contraction $q \in \mathcal M$ such that 
    \begin{equation}\label{eq:rr0-lemma}
        \|cq - q\|_{2, X} < \epsilon,\ \|q a - a\|_{2, X} < \epsilon,\ \|q^2 - q\|_{2, X} < \epsilon,\ \text{and}\ \|p - q\|_{2, X} < \sqrt{5\delta}. 
    \end{equation}

\label{def:tracial-subequiv}
    Let $A$ be a $C^*$-algebra and let $X \subseteq T(A)$ be a compact convex set.  For $n \in \mathbb N$ and $a, b \in M_n(A)_{+}$, write $a \precsim_X b$ if there is a sequence $(v_m)_{m=1}^\infty \subseteq M_n(A)$ such that 
    \begin{equation} 
        \lim_{m \rightarrow \infty} \|v_m^* b v_m - a \|_{2, X} = 0.
    \end{equation}
    We say $A$ has \emph{strict $(2, X)$-comparison} if for all $n \in \mathbb N$ and $a, b \in M_n(A)_+$ with $d_\tau(a) < d_\tau(b)$ for all $\tau \in X$, we have $a \precsim_X b$.

\label{lem:controlled-subequiv1}
	Let $A$ be a $C^*$-algebra and let $T(A)$ be a compact convex subset.  For all $a, b \in A_+$ and $w \in A$, there is $v \in A$ such that $\|v\| \leq \|a\|^{1/2}$, $vv^* \in \overline{bAb}$, and 
	\begin{equation}
		\quad \|v^*v - a\|_{2, \tau} \leq  \|wbw^* - a \|_{2, \tau}^{1/2}, \quad \tau \in T(A). 
	\end{equation}

Define $g \colon \mathbb R \rightarrow \mathbb R$ by
	\begin{equation}
		g(t) \coloneqq
		\begin{cases} 
			-\|a\|^{1/2}, & t \in \left(-\infty, \|a\|^{1/2}\right), \\ 
			t, & t \in \left[-\|a\|^{1/2}, \|a\|^{1/2}\right], \\
			\|a\|^{1/2}, & t \in \left(\|a\|^{1/2}, \infty\right), 
		\end{cases}
	\end{equation}
	and note that $g$ is continuous and odd.  By approximating $g(t)$ by linear combinations of monomials of odd degree, one can see that $g\left( \begin{pmatrix} 0 & w b^{1/2} \\ b^{1/2}w^* & 0 \end{pmatrix} \right)$ has the form 
	\begin{equation} 
		g\left( \begin{pmatrix} 0 & w b^{1/2} \\ b^{1/2}w^* & 0 \end{pmatrix} \right) = \begin{pmatrix} 0 & v^* \\ v & 0 \end{pmatrix} 
	\end{equation}
    for some $v \in A$.
	Note also that\footnote{When $g$ is a polynomial, write $g(t) = th(t^2)$ for a polynomial $h$.  Then using $g(t)^2=t^2h(t^2)^2$, we have
    \begin{equation}
    \begin{pmatrix} v^*v & \\ & vv^* \end{pmatrix} =
    \begin{pmatrix} wbw^* & \\ & b^{1/2}w^*wb^{1/2} \end{pmatrix} h\left(\begin{pmatrix} wbw^* & \\ & b^{1/2}w^*wb^{1/2} \end{pmatrix} \right)^2 \end{equation}
    and so $v^*v = wbw^* h(wbw^*)^2 = g((wbw^*)^{1/2})^2$ and likewise for the other one.}
	\begin{equation}
		v^*v = g((wbw^*)^{1/2})^2 \quad \text{and} \quad vv^* = g((b^{1/2} w^*w b^{1/2})^{1/2})^2.
	\end{equation}
	Then $\|v\| \leq \|a\|^{1/2}$ and $vv^* \in \overline{bAb}$.  To see the final estimate, note that for all $\tau \in T(A)$,
	\begin{equation}
		\begin{split}
			\|v^*v -a\|_{2, \tau}
			&= \|g((wbw^*)^{1/2})^2 - g(a^{1/2})^2 \|^2_{2, \tau} \\
			&\leq \| w b w^* - a\|_{2, \tau},
		\end{split}
	\end{equation}
	using Connes' joint distribution trick (\cite[Proposition~1.1]{Connes:Annals}) and noting that the function $G:[0, \infty) \rightarrow \mathbb R$ given by $t \mapsto g(t^{1/2})^2$ satisfies
	\begin{equation}
		G(t) = \begin{cases} 
			t, & t \in \left[0, \|a\|\right], \\ 
			\|a\|, & t \in \left(\|a\|, \infty\right),
		\end{cases}
	\end{equation}
    and so if $H,K \in L^2(\Omega,\mu)_+$ for a Radon measure space $(\Omega,\mu)$ then it follows that $\|G(H)-G(K)\|_{2,\mu} \leq \|H-K\|_{2,\mu}$.

\label{prop:controlled-subequiv2}
	Let $(\mathcal M, X)$ is a tracially complete $C^*$-algebra. Let $a, b \in \mathcal M_+$. Then the following are equivalent:
	\begin{enumerate}
		\item \label{it:controlled-subequiv2-1} The subequivalence $a \precsim_X b$ holds.
		\item \label{it:controlled-subequiv2-2} For all $\epsilon > 0$, there is $v \in \mathcal M$ such that 
		\begin{equation} 
			\|v^*v - a \|_{2, X} < \epsilon \quad \text{and} \quad vv^* \in \overline{b\mathcal Mb}.
		\end{equation}
		\item \label{it:controlled-subequiv2-3} For all $\epsilon > 0$, there is $v \in \mathcal M$ such that 
		\begin{equation} 
			\|v\| \leq \|a\|^{1/2}, \quad  \|v^*v - a \|_{2, X} < \epsilon, \quad \text{and} \quad vv^* \in \overline{b\mathcal Mb}.
		\end{equation}
		\item\label{it:controlled-subequiv2-4} For all $\epsilon > 0$, there is $\delta > 0$ and $v \in \mathcal M$ such that
		\begin{equation} \label{it:controlled-eq-4}
			\|v\| \leq \|a\|^{1/2}, \quad  \|v^*v - a \|_{2, X} < \epsilon, \quad \text{and} \quad vv^* \in \overline{(b-\delta)_+\mathcal M(b - \delta)_+}.
		\end{equation}
	\end{enumerate}

The implications \ref{it:controlled-subequiv2-4}$\Rightarrow$\ref{it:controlled-subequiv2-3}$\Rightarrow$\ref{it:controlled-subequiv2-2} are immediate.  We'll show \ref{it:controlled-subequiv2-2}$\Rightarrow$\ref{it:controlled-subequiv2-1}$\Rightarrow$\ref{it:controlled-subequiv2-4}.  

	Assume \ref{it:controlled-subequiv2-2} holds and fix $\epsilon > 0$. Choose $v \in \mathcal M$ as in \ref{it:controlled-subequiv2-2}.
    Since the net $\{f_\gamma(b)\}_{\gamma>0}$ forms an approximate unit for the hereditary subalgebra $\overline{b\mathcal M b}$, there exists $\delta > 0$, such that $\|f_\delta(b) v - v\| <  \epsilon/(\|v\|+1)$. Since $f_\delta(b) \precsim b$, there exists $w \in \mathcal M$ with $\|w^* b w - f_\delta(b)\| < \epsilon/(\|v\|^2+1)$.  Then $wv \in \mathcal M$ and satisfies
	\begin{equation}
		\begin{split}
			\|(wv)^* b (wv) - a\|_{2, X}
			&\leq \|v\|^2 \|w^*b w - f_\delta(b)\|_{2, X} + \|v\| \|f_\delta(b) v - v\| \\
			&\quad + \|v^*v - a\|_{2, X} \\
			& < 3\epsilon.
		\end{split}
	\end{equation}
	Therefore, $a \precsim_X b$.

	Now assume \ref{it:controlled-subequiv2-1} holds.  Given $\epsilon > 0$, there is $w \in \mathcal M$ such that $\|w^*b w - a\|_{2, X} < \epsilon$.  Then there is $\delta > 0$ such that 
	\begin{equation}
		\|w^*(b - \delta)_+ w - a \|_{2, X} < \epsilon.
	\end{equation}
	Apply Lemma~\ref{lem:controlled-subequiv1} with $a, (b - \delta)_+\in  \mathcal M_+$ and $w^*\in \mathcal M$, to obtain $v \in \mathcal M$ satisfying \eqref{it:controlled-eq-4}.

Since $a\precsim_X b$, using Proposition~\ref{prop:controlled-subequiv2}\ref{it:controlled-subequiv2-4},  for $\epsilon > 0$,  there exists $\delta > 0$ and $v \in \mathcal M$, such that 
    \begin{equation} \label{110_trans_eq_1}
			\|v\| \leq \|a\|^{1/2}, \quad  \|v^*v - a \|_{2, X} < \epsilon, \quad \text{and} \quad vv^* \in \overline{(b-\delta)_+\mathcal M(b - \delta)_+}.
		\end{equation}
    Moreover, as $b\precsim_X c$,  let $w \in \mathcal M$ be such that 
	\begin{equation}\label{110_trans_eq_2}
		\|w^* c w - b \|_{2, X} < \delta \epsilon. 
	\end{equation}
	Define the continuous function $h \colon [0, \infty) \rightarrow [0, \infty)$ by
	\begin{equation}
		h(t) \coloneqq \begin{cases} \delta^{-1/2}, & t \in [0, \delta), \\t^{-1/2}, & t \in (\delta, \infty), \end{cases}
	\end{equation}
	so that $h(t)^2 t = f_\delta(t)$, for all $t \in [0, \infty)$. Since $f_\delta(b)(b-\delta)_+= (b-\delta)_+$, we see that  $f_\delta(b)v=v$. As $\|v\|\leq \|a\|^{1/2} $, $w h(b) v \in \mathcal M$ satisfies
	\begin{equation}
		\begin{array}{rcl}
			\| (wh(b)v)^* c (wh(b)v) - a \|_{2, X}
			&\leq& \|v^* h(b) (w^*cw - b) h(b) v \|_{2, X}\\
            & &\quad\quad + \| v^*h(b)^2 b v - a \|_{2, X} \\
            &\leq&  \|v\|^2 \|h\|^2 \|w^*c w - b \|_{2, X} \\
            & &\quad \quad +   \| v^* f_\delta(b)v - a \|_{2, X}\\
            & \stackrel{\eqref{110_trans_eq_2}}\leq& \|a\|\delta^{-1}(\delta\epsilon)  + \| v^*v - a \|_{2, X} \\
			&\stackrel{\eqref{110_trans_eq_1}}<& (\|a\| + 1)\epsilon,
		\end{array}
	\end{equation}
	which shows that $a \precsim_X c$.

Since the canonical map $A \rightarrow \mathcal M$ is isometric with respect to the uniform 2-norms, we may replace $A$ with its image under this map and identify $A$ with a $\|\cdot\|_{2, X}$-dense $C^*$-subalgebra of $\mathcal M$.

	First, suppose that $(\mathcal M, X)$ has strict $(2, X)$-comparison. Fix $n \in \mathbb N$ and let $a, b \in M_n(A)_+$ be such that $d_\tau(a) < d_\tau(b)$ for all $\tau \in X$.  Then $a \precsim_{X} b$ in $M_n(\mathcal M)$, and hence  $a \precsim_{X} b$ in $M_n(A)$ by Proposition~\ref{prop:dense-subalgebra}.

	Conversely, suppose that $A$ has strict $(2, X)$-comparison. Let $n \in \mathbb N$ and $a, b \in M_n(\mathcal M)_+$ be such that $d_\tau(a) < d_\tau(b)$.  Fix $\epsilon > 0$.  Then for all $\tau \in X$ and $\epsilon > 0$, there is $\delta > 0$ such that
	\begin{equation}
		\tau(f_\epsilon(a)) < \tau(f_\delta((b-\delta)_+)),\quad\tau\in X.
	\end{equation}
	Let $w \in M_n(\mathcal M)$ be such that
	\begin{equation}\label{0110_2normEq_00}
		\|w^* b w - f_\delta(b)\| < \epsilon.
	\end{equation}
	Let $a_0, b_0 \in M_n(A)$ be such that 
	\begin{equation}\label{0110_2normEq_0}
		\|a_0\| \leq \|a\|, \quad \|a - a_0\|_{2, X} < \epsilon, \quad \|f_\delta(b) - f_\delta(b_0)\|_{2, X} < \epsilon,
	\end{equation}
	and
	\begin{equation}
		\tau(f_\epsilon(a_0)) < \tau(f_\delta((b_0 - \delta)_+)), \quad \tau \in X.
	\end{equation}
	Then for each $\tau \in X$, we have
	\begin{equation}
		d_\tau((a_0 - \epsilon)_+) \leq \tau(f_\epsilon(a_0)) < \tau(f_\delta((b_0-\delta)_+)) < d_\tau((b_0 - \delta)_+),
	\end{equation}
	so $(a_0 - \epsilon)_+ \precsim_{X} (b_0 - \delta)_+$ in $M_n(A)$.  By Proposition~\ref{lem:controlled-subequiv1}, we can choose $v \in M_n(A)$ with $\|v\|^2 \leq \|(a_0 - \epsilon)_+\|$ such that  
	\begin{equation}\label{0110_2normEq_1}
		 \|v^* v - (a_0 - \epsilon)_+ \|_{2, X} < \epsilon \quad \text{and}\quad vv^* \in \overline{(b_0 - \delta)_+ M_n(A) (b_0 - \delta)_+}.
	\end{equation}
	In particular, we have
	\begin{equation}\label{0110_2normEq_2}
		\|v\|^2 \leq \|a\|, \quad \|v^*v - a\|_{2, X} < 2 \epsilon, \quad \text{and} \quad f_\delta(b_0) v = v.
	\end{equation}
	Now, $wv \in M_n(\mathcal M)$ satisfies
	\begin{equation}
		\begin{array}{rcl} 
			\|(wv)^* b (wv) - a \|_{2, X} 
			&\leq& \|v^* w^* b w v - v^* f_\delta(b) v \|_{2, X} \\ 
			&&\quad  + \|v^* f_\delta(b)v - v^* f_\delta(b_0) v\|_{2, X} \\
            &&\quad + \|v^*v - a \|_{2, X} \\
			&\stackrel{\eqref{0110_2normEq_2}}<& \|v\|^2 \|w^*b w - f_\delta(b)\| \\
            &&\quad + \|v\|^2 \|f_\delta(b) - f_\delta(b_0)\|_{2, X} + 2 \epsilon \\
			&\stackrel{\eqref{0110_2normEq_00}, \eqref{0110_2normEq_0}}<& (2 \|a\| + 2) \epsilon. 
		\end{array} 
	\end{equation} 
	Therefore, $a \precsim_{X} b$ in $M_n(\mathcal M)$.

\label{Thm:StrictComparisonEquivalences}
	For a tracially complete $C^*$-algebra $(\mathcal M, X)$, the following are equivalent.
	\begin{enumerate}
		\item \label{0110_TCC_eq_1} $(\mathcal M, X)$ has strict $(2, X)$-comparison.
		\item \label{0110_TCC_eq_2} $(\mathcal M^\omega, X^\omega)$ has strict $(2, X^\omega)$-comparison.
		\item\label{0110_TCC_eq_3} $\mathcal M^\omega$ has strict comparison with respect to $X^\omega$.
	\end{enumerate}

The implication \ref{0110_TCC_eq_3}$\Rightarrow$\ref{0110_TCC_eq_2} is trivial since for all $n \in \mathbb N$ and $a, b \in M_n(\mathcal M^\omega)_+$, $a \precsim b$ implies $a \precsim_{X^\omega} b$.  

	For the implication \ref{0110_TCC_eq_2}$\Rightarrow$\ref{0110_TCC_eq_1}, suppose $n \in \mathbb N$ and $a, b \in M_n(\mathcal M)_+$ with $d_\tau(a) < d_\tau(b)$ for all $\tau \in X$.  Then $d_\tau(a) < d_\tau(b)$ for all $\tau \in X^\omega$, so $a \precsim_{X^\omega} b$ by \ref{0110_TCC_eq_2}.  Hence for  $\epsilon > 0$, there is $v \in M_n(\mathcal M^\omega)$ with $\|v^* b v - a \|_{2, X^\omega} < \epsilon$.  Let $(v_k)_{k=1}^\infty \in M_n(\mathcal M)$ be a sequence representing $v$ and note that
	\begin{equation}
		\lim_{k \rightarrow \omega} \|v_k^*b v_k - a \|_{2, X} = \|v^* b v - a \|_{2, X^\omega} < \epsilon,
	\end{equation}
	so for some $k \in \mathbb N$, we have $v_k \in M_n(\mathcal M)$ and $\|v_k^*b v_k - a \|_{2, X} < \epsilon$.  This shows $a \precsim_{X} b$, so \ref{0110_TCC_eq_1} holds.

	For the final implication, \ref{0110_TCC_eq_1}$\Rightarrow$\ref{0110_TCC_eq_3}, suppose $(\mathcal M, X)$ strict $(2, X)$-comparison.  Suppose further $n\in \mathbb N$ and $a, b \in M_n(\mathcal M^\omega)_+$ such that $d_\tau(a) < d_\tau(b)$ for all $\tau \in X^\omega$.  Fix $\epsilon > 0$ and let $\delta > 0$ be such that 
	\begin{equation}
		\tau(f_\epsilon(a)) < \tau(f_\delta((b-\delta)_+)), \quad \tau \in X^\omega.
	\end{equation}
	 Let $(a_k)_{k=1}^\infty, (b_k)_{k=1}^\infty \subseteq M_n(\mathcal M)$  be  sequences representing $a$ and $b$, respectively. Then there is a set $K \in \omega$ such that 
	\begin{equation}
		\tau(f_\epsilon(a_k)) < \tau(f_\delta((b_k-\delta)_+)), \quad \tau \in X,\ k \in K.
	\end{equation}	
	For each $k \in K$, we have
	\begin{equation}
		d_\tau((a_k - \epsilon)_+) \leq \tau(f_\epsilon(a_k)) < \tau(f_\delta((b_k-\delta)_+)) \leq d_\tau((b_k - \delta)_+), \quad \tau \in X, 
	\end{equation}	
	and hence by strict $(2, X)$-comparison of $\mathcal M$, there is $v_k \in M_n(\mathcal M)$ such that
	\begin{equation}
		\|v_k\| \leq \|a\|^{1/2}, \quad \|v_k^*v_k - (a_k - \epsilon)_+ \|_{2, X_n} < \frac1k, \quad \text{and} \quad f_\delta(b_k) v_k = v_k.
	\end{equation}
	For $k \in \omega \setminus K$, set $v_k = 0$ and note that $(v_k)_{k=1}^\infty \in M_n(\mathcal M)$ is a bounded sequence.  If $v \in M_n(\mathcal M^\omega)$ denotes the induced element, then $v^*v = (a - \epsilon)_+$ and $f_\delta(b)v = v$.  This shows $(a - \epsilon)_+ \precsim f_\delta(b) \precsim b$.  As $\epsilon > 0$ was arbitrary, $a \precsim b$, which proves \ref{0110_TCC_eq_3}.

\label{PurenessThm-body} Let $(\mathcal{M},X)$ be a II$_1$ factorial tracially complete $C^*$-algebra.  The following are equivalent:
\begin{enumerate}
    \item \label{it:Pureness.1-body} $(\mathcal{M},X)$ has strict $(2, X)$-comparison and has approximately constant rank functions;
    \item \label{it:Pureness.3-body}  $\mathcal M$ has strict comparison with respect to $X$ and $\mathcal M$ has divisible unit;
    \item \label{it:Pureness.4-body}  $(\mathcal{M},X)$ has classification of projections and $\mathcal M$ has real rank zero.
\end{enumerate}
In this case, $T(\mathcal M) = X$ and $\mathcal M$ is pure and has stable rank one.

\label{cor:regular}
    Let $A$ be a $C^*$-algebra such that $T(A)$ is non-empty and compact.  Suppose $A$ has strict comparison with respect to $T(A)$ and the class of a strictly positive element in $A$ is almost divisible.  Then both $(\overline{A}{}^{T(A)}, T(A))$ and $(A^\omega, \overline {T_\omega(A)})$ are regular.
    Further, a II$_1$ factorial tracially complete $C^*$-algebra $(\mathcal M, X)$ is regular if and only if $(\mathcal M^\omega, X^\omega)$ is regular.
